(89, 'text', 'Berusaha untuk tidak mencampuri hal tersebut karena setiap orang punyak hak asasi terhadap privasi masing-masing individu', 18, 2, NULL, '2024-10-10 16:15:27', '2024-10-10 16:15:27'),
(90, 'text', 'Secara terpaksa membatlakan rencana dengan pimpinan perusahaan dan menemui pihak pengurus rumah ibadah untuk menyampaikan rasa simpati atas musibah yang menimpa', 19, 4, NULL, '2024-10-10 16:16:42', '2024-10-10 16:16:42'),
(91, 'text', 'Mensuplai semua alat-alat yang dibutuhkan oleh rumah ibadah tersebut untuk merapikan puing-puing akibat gempa dan kemudian pergi berlibur dengan pimpinan perusahaan', 19, 2, NULL, '2024-10-10 16:16:42', '2024-10-10 16:16:42'),
(92, 'text', 'Menyebarkan informais tersebut kepada tetangga lain yang sempat untuk membantu pengurus rumah ibadah merapikan area rumah ibadah tersebut', 19, 1, NULL, '2024-10-10 16:16:42', '2024-10-10 16:16:42'),
(93, 'text', 'Secara terpaksa membatalkan rencana dengan pimpinan perusahaan dan ikut membantu merapikan puing-puing di rumah ibadah agama akibat gempa', 19, 5, NULL, '2024-10-10 16:16:42', '2024-10-10 16:16:42'),
(94, 'text', 'Membatalkan rencana berlibur dan menemui pihak pengurus rumah ibadah untuk memberikan sumbangan uang', 19, 3, NULL, '2024-10-10 16:16:42', '2024-10-10 16:16:42'),
(95, 'text', 'Memilih perusahaan yang menawarkan harga termurah untuk menghemat anggaran', 20, 2, NULL, '2024-10-10 16:21:16', '2024-10-10 16:21:16'),
(96, 'text', 'Memilih perusahaan dengan teknologi terbaru agar jaringan lebih canggih dan mutakhir', 20, 4, NULL, '2024-10-10 16:21:16', '2024-10-10 16:21:16'),
(97, 'text', 'Menjajaki kesepakatan dengan perusahaan yang menawarkan keuntungan jangka panjang bagi masyarakat setempat.', 20, 5, NULL, '2024-10-10 16:21:16', '2024-10-10 16:21:16'),
(98, 'text', 'Mengutamakan perusahaan yang memberikan keuntungan finansial yang besar bagi Anda pribadi.', 20, 1, NULL, '2024-10-10 16:21:16', '2024-10-10 16:21:16'),
(99, 'text', 'Bekerjasama dengan perusahaan yang sudah dikenal dan memiliki reputasi baik di daerah tersebut.', 20, 3, NULL, '2024-10-10 16:21:16', '2024-10-10 16:21:16'),
(100, 'text', 'Mengadakan pertemuan dengan perwakilan perusahaan untuk memahami kebutuhan industri dan menyesuaikan program magang dengan kualifikasi yang dibutuhkan.', 21, 5, NULL, '2024-10-10 16:23:12', '2024-10-10 16:23:12'),
(101, 'text', 'Meminta para dosen untuk mengarahkan mahasiswa agar fokus pada peningkatan keterampilan teknis sehingga lebih mudah diterima di perusahaan.', 21, 3, NULL, '2024-10-10 16:23:12', '2024-10-10 16:23:12'),
(102, 'text', 'Menghubungi perusahaan-perusahaan besar untuk membuat program magang terstruktur yang dapat memberikan pengalaman bagi mahasiswa dari berbagai jurusan.', 21, 4, NULL, '2024-10-10 16:23:12', '2024-10-10 16:23:12'),
(103, 'text', 'Menyediakan seminar dan pelatihan khusus bagi mahasiswa untuk mempersiapkan mereka dengan keterampilan yang dibutuhkan sebelum mengikuti magang.', 21, 2, NULL, '2024-10-10 16:23:12', '2024-10-10 16:23:12'),
(104, 'text', 'Menjalin kerja sama jangka panjang dengan perusahaan kecil yang memiliki hubungan baik dengan Anda untuk menjamin keberlanjutan program magang.', 21, 1, NULL, '2024-10-10 16:23:12', '2024-10-10 16:23:12'),
(105, 'text', 'Mengikuti acara yang fokus pada strategi komunikasi efektif dalam penulisan.', 22, 4, NULL, '2024-10-10 16:25:12', '2024-10-10 16:25:12'),
(106, 'text', 'Menghadiri acara di lain kesempatan dan fokus pada pekerjaannya saat ini.', 22, 1, NULL, '2024-10-10 16:25:12', '2024-10-10 16:25:12'),
(107, 'text', 'Mendaftar acara yang memberikan materi seputar tren terbaru dalam industri penulisan.', 22, 3, NULL, '2024-10-10 16:25:12', '2024-10-10 16:25:12'),
(108, 'text', 'Menghadiri acara yang menawarkan kesempatan untuk mempublish buku atau tulisan yang sedang ia kerjakan.', 22, 2, NULL, '2024-10-10 16:25:12', '2024-10-10 16:25:12'),
(109, 'text', 'Menghadiri acara yang memungkinkan untuk bertemu dengan banyak penulis berpengalaman agar memperluas jaringan', 22, 5, NULL, '2024-10-10 16:25:12', '2024-10-10 16:25:12'),
(110, 'text', 'Mengundang semua anggota tim agar mendapatkan masukan yang beragam dan membuat keputusan bersama.', 23, 5, NULL, '2024-10-10 16:26:56', '2024-10-10 16:26:56'),
(111, 'text', 'Menyusun agenda rapat dengan jelas agar rapat berlangsung efektif dan terarah', 23, 4, NULL, '2024-10-10 16:26:56', '2024-10-10 16:26:56'),
(112, 'text', 'Menyusun laporan singkat tanpa mengadakan rapat untuk menghemat waktu.', 23, 1, NULL, '2024-10-10 16:26:56', '2024-10-10 16:26:56'),
(113, 'text', 'Mengundang beberapa anggota tim berpengalamaan yang terlibat langsung dalam proyek.', 23, 3, NULL, '2024-10-10 16:26:56', '2024-10-10 16:26:56'),
(114, 'text', 'Meminta tim untuk mengumpulkan beberapa rencana strategi dan merapatkannya dengan atasan.', 23, 2, NULL, '2024-10-10 16:26:56', '2024-10-10 16:26:56'),
(115, 'text', 'Memperhatikan setiap masukan dengan serius dan berusaha belajar dari setiap kritik untuk terus berkembang sebagai chef.', 24, 5, NULL, '2024-10-10 16:29:17', '2024-10-10 16:29:17'),
(116, 'text', 'Membuat daftar masukan yang diterima, kemudian menyusun langkah-langkah perbaikan yang terstruktur sesuai dengan prioritas.', 24, 4, NULL, '2024-10-10 16:29:17', '2024-10-10 16:29:17'),
(117, 'text', 'Mengajak rekan kerja untuk berbagi pengalaman dan mendiskusikan cara-cara memperbaiki kelemahan yang disampaikan.', 24, 3, NULL, '2024-10-10 16:29:17', '2024-10-10 16:29:17'),
(118, 'text', 'Meminta masukan langsung dari kepala chef setiap kali ada hal yang tidak dipahami untuk perbaikan yang lebih tepat.', 24, 1, NULL, '2024-10-10 16:29:17', '2024-10-10 16:29:17'),
(119, 'text', 'Mencatat setiap masukan yang diterima dan menggunakannya sebagai bahan evaluasi mingguan untuk mengukur perkembangan diri.', 24, 2, NULL, '2024-10-10 16:29:17', '2024-10-10 16:29:17'),
(120, 'text', 'Mengamati karakter setiap rekan kerja terlebih dahulu sebelum mulai membangun komunikasi secara bertahap.', 25, 4, NULL, '2024-10-10 16:33:12', '2024-10-10 16:33:12'),
(121, 'text', 'Berfokus pada tugas Anda sendiri terlebih dahulu sebelum membangun hubungan dengan rekan kerja.', 25, 2, NULL, '2024-10-10 16:33:12', '2024-10-10 16:33:12'),
(122, 'text', 'Mengajak rekan kerja berbincang secara informal untuk membangun kepercayaan dan kenyamanan.', 25, 3, NULL, '2024-10-10 16:33:12', '2024-10-10 16:33:12'),
(123, 'text', 'Membangun komunikasi dengan beberapa rekan kerja yang memiliki peran penting dalam proyek yang sama dengan Anda.', 25, 1, NULL, '2024-10-10 16:33:12', '2024-10-10 16:33:12'),
(124, 'text', 'Menghadiri setiap pertemuan tim dan berusaha terlibat aktif dalam diskusi untuk memahami cara kerja mereka', 25, 5, NULL, '2024-10-10 16:33:12', '2024-10-10 16:33:12'),
(125, 'text', 'Menerima semua saran dengan terbuka dan berusaha memperbaiki setiap aspek yang disarankan.', 26, 5, NULL, '2024-10-10 16:34:06', '2024-10-10 16:34:06'),
(126, 'text', 'Meminta rekan kerja untuk menyampaikan saran secara langsung agar lebih memahami poin-poin yang bisa diperbaiki.', 26, 3, NULL, '2024-10-10 16:34:06', '2024-10-10 16:34:06'),
(127, 'text', 'Mengumpulkan semua saran dan menyusun rencana perbaikan bertahap sesuai prioritas yang penting.', 26, 4, NULL, '2024-10-10 16:34:06', '2024-10-10 16:34:06'),
(128, 'text', 'Mencari  umpan  balik  tambahan  dari  orang  yang  lebih  berpengalaman  untuk  mendapatkan perspektif yang lebih luas.', 26, 2, NULL, '2024-10-10 16:34:06', '2024-10-10 16:34:06'),
(129, 'text', 'Menganalisis saran yang diterima dan mengimplementasikannya ke dalam rencana pengembangan jangka panjang.', 26, 1, NULL, '2024-10-10 16:34:06', '2024-10-10 16:34:06'),
(130, 'text', 'Menerapkan protokol keamanan data yang ketat serta membangun sistem kolaborasi yang lebih terintegrasi.', 27, 4, NULL, '2024-10-10 16:35:20', '2024-10-10 16:35:20'),
(131, 'text', 'Menekankan pentingnya tenggat waktu kepada tim dan memberikan teguran jika tugas tidak selesai tepat waktu.', 27, 3, NULL, '2024-10-10 16:35:20', '2024-10-10 16:35:20'),
(132, 'text', 'Meminta tim untuk lebih meningkatkan keterampilan manajemen waktu agar pola kerja lebih efektif.', 27, 2, NULL, '2024-10-10 16:35:20', '2024-10-10 16:35:20'),
(133, 'text', 'Menyusun sistem pelaporan otomatis dan menetapkan waktu rapat rutin untuk meningkatkan komunikasi dan pemantauan proyek.', 27, 5, NULL, '2024-10-10 16:35:20', '2024-10-10 16:35:20'),
(134, 'text', 'Mengurangi beban kerja tim dengan menugaskan sebagian proyek kepada pihak eksternal yang dapat membantu.', 27, 1, NULL, '2024-10-10 16:35:20', '2024-10-10 16:35:20'),
(135, 'text', 'Memberikan pelatihan tambahan kepada staf agar lebih sigap dalam menangani permintaan dari masyarakat.', 28, 4, NULL, '2024-10-10 16:36:38', '2024-10-10 16:36:38'),
(136, 'text', 'Meminta pimpinan untuk menambah jumlah staf agar beban kerja saat ini bisa dikurangi.', 28, 2, NULL, '2024-10-10 16:36:38', '2024-10-10 16:36:38'),
(137, 'text', 'Mengusulkan penggunaan teknologi baru untuk mempercepat alur layanan dan mempermudah komunikasi antarbagian.', 28, 3, NULL, '2024-10-10 16:36:38', '2024-10-10 16:36:38'),
(138, 'text', 'Menyusun sistem laporan harian yang memantau kinerja masing-masing staf dan bagian.', 28, 1, NULL, '2024-10-10 16:36:38', '2024-10-10 16:36:38'),
(139, 'text', 'Mengadakan rapat rutin dengan seluruh bagian untuk mengevaluasi setiap proses dan mempercepat koordinasi antarbagian.', 28, 5, NULL, '2024-10-10 16:36:38', '2024-10-10 16:36:38'),
(140, 'text', 'Menjalin komunikasi intensif dengan pimpinan instansi terkait untuk membahas prioritas layanan dan memastikan dukungan yang tepat sesuai dengan kebutuhan warga.', 29, 5, NULL, '2024-10-10 16:37:45', '2024-10-10 16:37:45'),
(141, 'text', 'Menyusun proposal lengkap yang mencakup data kebutuhan warga untuk mendapatkan dukungan dari setiap instansi terkait.', 29, 4, NULL, '2024-10-10 16:37:45', '2024-10-10 16:37:45'),
(142, 'text', 'Menugaskan staf untuk melakukan survei langsung di lapangan guna mengetahui layanan mana yang paling dibutuhkan masyarakat.', 29, 3, NULL, '2024-10-10 16:37:45', '2024-10-10 16:37:45'),
(143, 'text', 'Membuat rencana kerja tahunan yang mengutamakan kerja sama dengan instansi terkait, lalu disosialisasikan kepada warga.', 29, 1, NULL, '2024-10-10 16:37:45', '2024-10-10 16:37:45'),
(144, 'text', 'Mengadakan diskusi dengan perangkat desa lain untuk mengidentifikasi kendala yang dihadapi terkait akses layanan kesehatan.', 29, 2, NULL, '2024-10-10 16:37:45', '2024-10-10 16:37:45'),
(145, 'text', 'Menggunakan bahasa yang sopan, santun, dan menghormati pasien Anda, serta menghindari bahasa yang kasar, menyinggung, atau merendahkan.', 30, 2, NULL, '2024-10-10 16:39:39', '2024-10-10 16:39:39'),
(146, 'text', 'Menyediakan waktu yang cukup untuk mendengarkan keluhan, pertanyaan, atau saran pasien Anda, serta memberikan jawaban atau penjelasan yang jelas, lengkap, dan mudah dimengerti.', 30, 5, NULL, '2024-10-10 16:39:39', '2024-10-10 16:39:39'),
(147, 'text', 'Menunjukkan sikap yang peduli, empati, dan simpati terhadap kondisi pasien Anda, serta memberikan dukungan moral atau motivasi yang sesuai.', 30, 4, NULL, '2024-10-10 16:39:39', '2024-10-10 16:39:39'),
(148, 'text', 'Menindaklanjuti perkembangan kesehatan pasien Anda, baik secara langsung maupun melalui telepon, email, atau media sosial, serta memberikan saran atau rekomendasi yang berguna.', 30, 3, NULL, '2024-10-10 16:39:39', '2024-10-10 16:39:39'),
(149, 'text', 'Menghargai hak dan privasi pasien Anda, serta menjaga kerahasiaan data dan informasi yang berkaitan dengan pasien Anda, kecuali jika ada izin atau kewajiban hukum.', 30, 1, NULL, '2024-10-10 16:39:39', '2024-10-10 16:39:39'),
(150, 'text', 'Menjalin kerja sama dengan pemasok obat dan peralatan medis untuk mendapatkan harga yang lebih kompetitif dan efisien.', 31, 1, NULL, '2024-10-10 16:41:05', '2024-10-10 16:41:05'),
(151, 'text', 'Menyusun rencana anggaran yang rinci dan mendistribusikan sumber daya sesuai prioritas kebutuhan di setiap cabang.', 31, 4, NULL, '2024-10-10 16:41:05', '2024-10-10 16:41:05'),
(152, 'text', 'Mengadakan evaluasi berkala untuk memantau penggunaan sumber daya dan memastikan efisiensi di semua cabang rumah sakit.', 31, 5, NULL, '2024-10-10 16:41:05', '2024-10-10 16:41:05'),
(153, 'text', 'Mengadakan pelatihan bagi tenaga medis untuk meningkatkan keterampilan mereka dalam memaksimalkan penggunaan peralatan dan obat-obatan.', 31, 3, NULL, '2024-10-10 16:41:05', '2024-10-10 16:41:05'),
(154, 'text', 'Mengurangi penggunaan peralatan medis yang jarang digunakan dan fokus pada pengadaan alat- alat yang lebih mendesak.', 31, 2, NULL, '2024-10-10 16:41:05', '2024-10-10 16:41:05'),
(155, 'text', 'A. Kesetiaan terhadap bangsa lebih penting daripada kepentingan pribadi.', 32, 0, NULL, '2024-10-10 16:41:35', '2024-10-10 16:41:35'),
(156, 'text', 'B. Kepentingan keluarga harus didahulukan dalam situasi kritis.', 32, 0, NULL, '2024-10-10 16:41:35', '2024-10-10 16:41:35'),
(157, 'text', 'C. Perjuangan nasional memerlukan pengorbanan yang tidak mudah.', 32, 5, NULL, '2024-10-10 16:41:35', '2024-10-10 16:41:35'),
(158, 'text', 'D. Prioritas hidup harus disesuaikan dengan kebutuhan bangsa.', 32, 0, NULL, '2024-10-10 16:41:35', '2024-10-10 16:41:35'),
(159, 'text', 'E. Fokus pada tujuan nasional lebih penting daripada urusan pribadi.', 32, 0, NULL, '2024-10-10 16:41:35', '2024-10-10 16:41:35'),
(160, 'text', 'Mengarahkan nasabah untuk menghubungi konsultan keuangan agar pengajuan pinjamannya lebih cepat disetujui.', 33, 2, NULL, '2024-10-10 16:42:25', '2024-10-10 16:42:25'),
(161, 'text', 'Menjelaskan dengan sopan kepada nasabah mengenai ketidaksesuaian dokumen dan memberikan petunjuk jelas untuk melengkapi kekurangan.', 33, 5, NULL, '2024-10-10 16:42:25', '2024-10-10 16:42:25'),
(162, 'text', 'Memberikan kesempatan kepada nasabah untuk melengkapi dokumen dalam waktu yang ditentukan tanpa harus memulai proses dari awal.', 33, 4, NULL, '2024-10-10 16:42:25', '2024-10-10 16:42:25'),
(163, 'text', 'Menyampaikan bahwa pengajuan tidak bisa diproses tanpa dokumen lengkap, dan menyarankan untuk datang kembali setelah semua dokumen tersedia.', 33, 3, NULL, '2024-10-10 16:42:25', '2024-10-10 16:42:25'),
(164, 'text', 'Menawarkan kepada nasabah untuk mengurus dokumennya yang kurang terlebih dahulu dan menunda pengajuan pinjaman dipekan depan agar tidak terburu-buru.', 33, 1, NULL, '2024-10-10 16:42:25', '2024-10-10 16:42:25'),
(165, 'text', 'A. Mengajarkan lagu-lagu kebangsaan dan sejarah perjuangan bangsa.', 34, 0, NULL, '2024-10-10 16:42:51', '2024-10-10 16:42:51'),
(166, 'text', 'B. Mengadakan lomba-lomba bertema nasionalisme setiap bulan.', 34, 0, NULL, '2024-10-10 16:42:51', '2024-10-10 16:42:51'),
(167, 'text', 'C. Mengajak siswa untuk mengunjungi tempat-tempat bersejarah.', 34, 0, NULL, '2024-10-10 16:42:51', '2024-10-10 16:42:51'),
(168, 'text', 'D. Mengintegrasikan nilai-nilai kebangsaan dalam mata pelajaran sehari-hari.', 34, 5, NULL, '2024-10-10 16:42:51', '2024-10-10 16:42:51'),
(169, 'text', 'E. Menggunakan media visual seperti film dan video yang menggambarkan perjuangan nasional.', 34, 0, NULL, '2024-10-10 16:42:51', '2024-10-10 16:42:51'),
(170, 'text', 'Memperkenalkan sistem penghargaan bagi karyawan yang berhasil meningkatkan kualitas pelayanan dan responsivitas.', 35, 1, NULL, '2024-10-10 16:43:50', '2024-10-10 16:43:50'),
(171, 'text', 'Melibatkan pelanggan dalam survei untuk mendapatkan masukan langsung terkait kualitas pelayanan dan saran perbaikan.', 35, 5, NULL, '2024-10-10 16:43:50', '2024-10-10 16:43:50'),
(172, 'text', 'Meninjau ulang kebijakan internal dan memperbaiki aturan yang memperlambat proses pelayanan.', 35, 3, NULL, '2024-10-10 16:43:50', '2024-10-10 16:43:50'),
(173, 'text', 'Mengalokasikan anggaran untuk menambah jumlah staf agar proses pelayanan lebih responsif menghadapi pelanggan.', 35, 2, NULL, '2024-10-10 16:43:50', '2024-10-10 16:43:50'),
(174, 'text', 'Mengadakan pertemuan dengan seluruh tim untuk membahas target baru yang akan meningkatkan kualitas pelayanan kepada pelanggan.', 35, 4, NULL, '2024-10-10 16:43:50', '2024-10-10 16:43:50'),
(175, 'text', 'A. Agar kita tidak melupakan sejarah perjuangan bangsa.', 36, 0, NULL, '2024-10-10 16:44:29', '2024-10-10 16:44:29'),
(176, 'text', 'B. Untuk memastikan bahwa semangat mereka tetap hidup dalam generasi sekarang.', 36, 5, NULL, '2024-10-10 16:44:29', '2024-10-10 16:44:29'),
(177, 'text', 'C. Agar kita memiliki teladan dalam menghadapi tantangan masa kini.', 36, 0, NULL, '2024-10-10 16:44:29', '2024-10-10 16:44:29'),
(178, 'text', 'D. Untuk menghormati pengorbanan mereka demi kemerdekaan bangsa.', 36, 0, NULL, '2024-10-10 16:44:29', '2024-10-10 16:44:29'),
(179, 'text', 'E. Untuk menjaga agar nilai-nilai kebangsaan tetap terjaga di masyarakat.', 36, 0, NULL, '2024-10-10 16:44:29', '2024-10-10 16:44:29'),
(180, 'text', 'Membuat sistem pemantauan dan evaluasi berkala untuk memastikan distribusi pangan tepat sasaran di seluruh wilayah.', 37, 4, NULL, '2024-10-10 16:44:51', '2024-10-10 16:44:51'),
(181, 'text', 'Meluncurkan program kerja sama dengan masyarakat lokal untuk memfasilitasi distribusi pangan ke daerah-daerah yang sulit dijangkau.', 37, 3, NULL, '2024-10-10 16:44:51', '2024-10-10 16:44:51'),
(182, 'text', 'Mengalokasikan sebagian anggaran untuk membangun infrastruktur yang mendukung kelancaran distribusi di wilayah terpencil.', 37, 2, NULL, '2024-10-10 16:44:51', '2024-10-10 16:44:51'),
(183, 'text', 'Melakukan pemetaan ulang wilayah untuk mengidentifikasi daerah yang paling membutuhkan prioritas dalam pendistribusian pangan.', 37, 1, NULL, '2024-10-10 16:44:51', '2024-10-10 16:44:51'),
(184, 'text', 'Menugaskan tim khusus untuk fokus pada wilayah yang paling sulit dijangkau agar distribusi pangan dapat lebih cepat.', 37, 5, NULL, '2024-10-10 16:44:51', '2024-10-10 16:44:51'),
(185, 'text', 'A. Dengan membentuk aliansi antar organisasi untuk memperkuat pergerakan nasional.', 38, 0, NULL, '2024-10-10 16:45:43', '2024-10-10 16:45:43'),
(186, 'text', 'B. Dengan mengadakan kongres pemuda untuk menyatukan berbagai kelompok pergerakan.', 38, 0, NULL, '2024-10-10 16:45:43', '2024-10-10 16:45:43'),
(187, 'text', 'C. Dengan mengorganisir demonstrasi besar-besaran melawan penjajah.', 38, 0, NULL, '2024-10-10 16:45:43', '2024-10-10 16:45:43'),
(188, 'text', 'D. Dengan mengembangkan pendidikan untuk meningkatkan kesadaran nasional.', 38, 5, NULL, '2024-10-10 16:45:43', '2024-10-10 16:45:43'),
(189, 'text', 'E. Dengan membentuk sayap militer untuk melawan penjajah secara langsung.', 38, 0, NULL, '2024-10-10 16:45:43', '2024-10-10 16:45:43'),
(190, 'text', 'Menjelaskan kepada tamu bahwa pelayanan minggu lalu diberikan oleh customer service yang lain dan menawarkan untuk membantu menyelesaikan masalahnya', 39, 3, NULL, '2024-10-10 16:46:02', '2024-10-10 16:46:02'),
(191, 'text', 'Mendengarkan keluhan tamu dengan empati dan meminta maaf atas ketidaknyamanan yang dialami, dan memberikan alternatif penyelesaian keluhan yang efektif', 39, 5, NULL, '2024-10-10 16:46:02', '2024-10-10 16:46:02'),
(192, 'text', 'Mengarahkan tamu untuk menghubungi customer service yang memberikan pelayanan minggu lalu agar masalah dapat diselesaikan lebih tepat.', 39, 1, NULL, '2024-10-10 16:46:02', '2024-10-10 16:46:02'),
(193, 'text', 'Mencatat keluhan tamu dan berjanji akan menyampaikan masalah tersebut kepada pihak yang bertanggung jawab untuk ditindaklanjuti.', 39, 4, NULL, '2024-10-10 16:46:02', '2024-10-10 16:46:02'),
(194, 'text', 'Menyampaikan bahwa masalah tersebut sudah bukan tanggung jawab Fira dan meminta tamu menunggu customer service lain yang melayani sebelumnya.', 39, 2, NULL, '2024-10-10 16:46:02', '2024-10-10 16:46:02'),
(195, 'text', 'A. Mengikuti program pelatihan bela negara yang diselenggarakan oleh pemerintah.', 40, 0, NULL, '2024-10-10 16:46:47', '2024-10-10 16:46:47'),
(196, 'text', 'B. Menjaga ketertiban dan keamanan di lingkungan tempat tinggal.', 40, 5, NULL, '2024-10-10 16:46:47', '2024-10-10 16:46:47'),
(197, 'text', 'C. Membantu korban bencana alam melalui kegiatan sosial.', 40, 0, NULL, '2024-10-10 16:46:47', '2024-10-10 16:46:47'),
(198, 'text', 'D. Berpartisipasi dalam pemilu untuk memilih pemimpin yang pro-rakyat.', 40, 0, NULL, '2024-10-10 16:46:47', '2024-10-10 16:46:47'),
(199, 'text', 'E. Menyebarkan informasi tentang pentingnya kesadaran bela negara.', 40, 0, NULL, '2024-10-10 16:46:47', '2024-10-10 16:46:47'),
(200, 'text', 'A. Mengikuti kegiatan sosial yang mendukung ketahanan nasional.', 41, 0, NULL, '2024-10-10 16:47:43', '2024-10-10 16:47:43'),
(201, 'text', 'B. Berpartisipasi aktif dalam organisasi kepemudaan yang mempromosikan nilai-nilai bela negara.', 41, 5, NULL, '2024-10-10 16:47:43', '2024-10-10 16:47:43'),
(202, 'text', 'C. Mengembangkan keterampilan yang dapat digunakan untuk membangun bangsa.', 41, 0, NULL, '2024-10-10 16:47:43', '2024-10-10 16:47:43'),
(203, 'text', 'D. Menyebarkan informasi yang mendukung kesadaran bela negara melalui media sosial.', 41, 0, NULL, '2024-10-10 16:47:43', '2024-10-10 16:47:43'),
(204, 'text', 'E. Mengikuti pelatihan kepemimpinan yang berfokus pada penguatan karakter bangsa.', 41, 0, NULL, '2024-10-10 16:47:43', '2024-10-10 16:47:43'),
(205, 'text', 'Menggunakan anggaran untuk memperbarui sistem keamanan teknologi informasi agar perusahaan terhindar dari risiko serangan siber.', 42, 3, NULL, '2024-10-10 16:47:44', '2024-10-10 16:47:44'),
(206, 'text', 'Menyusun rencana jangka panjang untuk memperbarui keamanan teknologi secara bertahap, dengan memprioritaskan pelatihan untuk meningkatkan kesadaran karyawan terhadap ancaman siber.', 42, 4, NULL, '2024-10-10 16:47:44', '2024-10-10 16:47:44'),
(207, 'text', 'Menyediakan pelatihan bagi karyawan tentang cara mengidentifikasi ancaman keamanan siber sambil menunda pembaruan teknologi untuk sementara waktu.', 42, 2, NULL, '2024-10-10 16:47:44', '2024-10-10 16:47:44'),
(208, 'text', 'Mengalokasikan sebagian anggaran untuk memperbarui sistem keamanan, sambil menyelenggarakan pelatihan dasar keamanan informasi bagi karyawan.', 42, 5, NULL, '2024-10-10 16:47:44', '2024-10-10 16:47:44'),
(209, 'text', 'Mengajukan anggaran tambahan untuk bisa memperbarui sistem keamanan sekaligus menyelenggarakan pelatihan karyawan dengan lebih efektif di masa depan.', 42, 1, NULL, '2024-10-10 16:47:44', '2024-10-10 16:47:44'),
(210, 'text', 'A. Mengurangi ketergantungan pada produk impor dengan membeli produk lokal.', 43, 5, NULL, '2024-10-10 16:48:34', '2024-10-10 16:48:34'),
(211, 'text', 'B. Membuka usaha kecil yang mempekerjakan warga lokal.', 43, 0, NULL, '2024-10-10 16:48:34', '2024-10-10 16:48:34'),
(212, 'text', 'C. Mengikuti pelatihan kewirausahaan untuk meningkatkan keterampilan bisnis.', 43, 0, NULL, '2024-10-10 16:48:34', '2024-10-10 16:48:34'),
(213, 'text', 'D. Menyimpan uang di bank-bank nasional untuk mendukung sistem keuangan domestik.', 43, 0, NULL, '2024-10-10 16:48:34', '2024-10-10 16:48:34'),
(214, 'text', 'E. Mengembangkan inovasi yang dapat meningkatkan daya saing produk dalam negeri.', 43, 0, NULL, '2024-10-10 16:48:34', '2024-10-10 16:48:34'),
(215, 'text', 'A. Mendorong pemuda Sumatra untuk mengikuti pendidikan formal dan non-formal.', 44, 5, NULL, '2024-10-10 16:49:35', '2024-10-10 16:49:35'),
(216, 'text', 'B. Mengadakan pelatihan militer bagi pemuda untuk memperkuat pertahanan lokal.', 44, 0, NULL, '2024-10-10 16:49:35', '2024-10-10 16:49:35'),
(217, 'text', 'C. Mengorganisir demonstrasi besar-besaran menuntut kemerdekaan.', 44, 0, NULL, '2024-10-10 16:49:35', '2024-10-10 16:49:35'),
(218, 'text', 'D. Membentuk aliansi dengan organisasi pemuda lainnya untuk memperkuat pergerakan nasional.', 44, 0, NULL, '2024-10-10 16:49:35', '2024-10-10 16:49:35'),
(219, 'text', 'E. Menyebarkan ide-ide tentang pentingnya pendidikan dalam memperkuat bangsa.', 44, 0, NULL, '2024-10-10 16:49:35', '2024-10-10 16:49:35'),
(220, 'text', 'Menggunakan aplikasi kolaborasi yang memungkinkan tim berbagi dan mengedit dokumen bersama secara langsung.', 45, 4, NULL, '2024-10-10 16:50:14', '2024-10-10 16:50:14'),
(221, 'text', 'Memilih aplikasi kolaborasi dengan fitur pengingat dan penugasan tugas, agar semua anggota tim menyelesaikan tugas tepat waktu', 45, 2, NULL, '2024-10-10 16:50:14', '2024-10-10 16:50:14'),
(222, 'text', 'Mengadakan pelatihan sederhana tentang cara menggunakan aplikasi kolaborasi dan berbagi tips untuk meningkatkan efisiensi.', 45, 3, NULL, '2024-10-10 16:50:14', '2024-10-10 16:50:14'),
(223, 'text', 'Menjadwalkan pertemuan rutin melalui aplikasi kolaborasi untuk memudahkan diskusi dan memantau kemajuan kampanye.', 45, 5, NULL, '2024-10-10 16:50:14', '2024-10-10 16:50:14'),
(224, 'text', 'Mengaktifkan notifikasi dalam aplikasi kolaborasi agar semua anggota tim tahu setiap perubahan atau pembaruan penting.', 45, 1, NULL, '2024-10-10 16:50:14', '2024-10-10 16:50:14'),
(225, 'text', 'A. Berpartisipasi dalam program pengawasan lingkungan di wilayah perbatasan.', 46, 0, NULL, '2024-10-10 16:50:24', '2024-10-10 16:50:24'),
(226, 'text', 'B. Mendukung program pemerintah yang bertujuan meningkatkan ketahanan pangan.', 46, 5, NULL, '2024-10-10 16:50:24', '2024-10-10 16:50:24'),
(227, 'text', 'C. Menggunakan hak pilih dengan bijak dalam setiap pemilihan umum.', 46, 0, NULL, '2024-10-10 16:50:24', '2024-10-10 16:50:24'),
(228, 'text', 'D. Menyumbangkan dana untuk organisasi yang bergerak di bidang keamanan nasional.', 46, 0, NULL, '2024-10-10 16:50:24', '2024-10-10 16:50:24'),
(229, 'text', 'E. Meningkatkan kesadaran masyarakat tentang pentingnya bela negara melalui pendidikan.', 46, 0, NULL, '2024-10-10 16:50:24', '2024-10-10 16:50:24'),
(230, 'text', 'Menerima jawaban pembicara tanpa bertindak lebih lanjut, karena merasa informasi yang diberikan sudah cukup untuk memahami masa depan AI.', 47, 3, NULL, '2024-10-10 16:52:19', '2024-10-10 16:52:19'),
(231, 'text', 'Mencari informasi lebih lanjut mengenai perkembangan teknologi AI melalui artikel, jurnal, atau sumber lain yang lebih mendalam untuk memperkaya pengetahuannya', 47, 5, NULL, '2024-10-10 16:52:19', '2024-10-10 16:52:19'),
(232, 'text', 'Menyampaikan pandangannya yang berbeda dari pendapat pembicara, karena merasa memiliki perspektif lain yang mungkin bisa memperkaya diskusi', 47, 4, NULL, '2024-10-10 16:52:19', '2024-10-10 16:52:19'),
(233, 'text', 'Mengakhiri sesi webinar dan diskusi, karena merasa jawaban yang diberikan tidak sesuai dengan ekspektasinya terkait AI.', 47, 2, NULL, '2024-10-10 16:52:19', '2024-10-10 16:52:19'),
(234, 'text', 'Meminta pembicara untuk mengubah jawaban yang telah diberikan, karena Sinta tidak sepenuhnya setuju dengan prospek AI yang dipaparkan.', 47, 1, NULL, '2024-10-10 16:52:19', '2024-10-10 16:52:19'),
(235, 'text', 'A. Mengutamakan kepentingan bersama dalam setiap pengambilan keputusan.', 48, 0, NULL, '2024-10-10 16:53:19', '2024-10-10 16:53:19'),
(236, 'text', 'B. Menjaga sikap toleransi dan menghormati perbedaan di masyarakat.', 48, 5, NULL, '2024-10-10 16:53:19', '2024-10-10 16:53:19'),
(237, 'text', 'C. Mengintegrasikan nilai-nilai Pancasila dalam setiap kebijakan pemerintah.', 48, 0, NULL, '2024-10-10 16:53:19', '2024-10-10 16:53:19'),
(238, 'text', 'D. Mengedukasi masyarakat tentang pentingnya Pancasila melalui program-program penyuluhan.', 48, 0, NULL, '2024-10-10 16:53:19', '2024-10-10 16:53:19'),
(239, 'text', 'E. Melibatkan semua golongan masyarakat dalam perencanaan pembangunan nasional.', 48, 0, NULL, '2024-10-10 16:53:19', '2024-10-10 16:53:19'),
(240, 'text', 'Mengikuti workshop dan sesi sharing tersebut sebagai pendengar saja tanpa bertanya atau memberikan pendapat, untuk mendapatkan informasi dasar terlebih dahulu.', 49, 3, NULL, '2024-10-10 16:53:23', '2024-10-10 16:53:23'),
(241, 'text', 'Mendaftar sebagai peserta aktif dalam workshop dan sesi sharing, serta mempersiapkan beberapa pertanyaan untuk meningkatkan pemahamannya tentang keamanan siber.', 49, 5, NULL, '2024-10-10 16:53:23', '2024-10-10 16:53:23'),
(242, 'text', 'Menghubungi panitia acara sebelum workshop untuk meminta materi pendahuluan agar dapat lebih siap menghadapi sesi tersebut.', 49, 2, NULL, '2024-10-10 16:53:23', '2024-10-10 16:53:23'),
(243, 'text', 'Bergabung dengan grup diskusi online komunitas Keamanan Siber Indonesia sebelum mengikuti workshop untuk membangun kepercayaan diri dan mendapatkan wawasan awal.', 49, 4, NULL, '2024-10-10 16:53:23', '2024-10-10 16:53:23'),
(244, 'text', 'Mengajak teman yang juga tertarik pada keamanan siber untuk mengikuti workshop bersama, sehingga Rina merasa lebih nyaman dan termotivasi.', 49, 1, NULL, '2024-10-10 16:53:23', '2024-10-10 16:53:23'),
(245, 'text', 'A. Menjamin hak semua warga negara untuk berpartisipasi dalam pemilihan umum.', 50, 5, NULL, '2024-10-10 16:54:15', '2024-10-10 16:54:15'),
(246, 'text', 'B. Menetapkan bahwa kekuasaan tertinggi berada di tangan presiden sebagai kepala negara.', 50, 0, NULL, '2024-10-10 16:54:15', '2024-10-10 16:54:15'),
(247, 'text', 'C. Mengatur bahwa semua keputusan politik harus melalui referendum nasional.', 50, 0, NULL, '2024-10-10 16:54:15', '2024-10-10 16:54:15'),
(248, 'text', 'D. Memastikan bahwa semua warga negara mendapatkan akses yang sama dalam pemilihan umum.', 50, 0, NULL, '2024-10-10 16:54:15', '2024-10-10 16:54:15'),
(249, 'text', 'E. Menyediakan pendidikan politik untuk meningkatkan partisipasi masyarakat dalam pemilu', 50, 0, NULL, '2024-10-10 16:54:15', '2024-10-10 16:54:15'),
(250, 'text', 'Memperbarui server perusahaan dan meningkatkan kapasitas penyimpanan cloud untuk memastikan dapat menangani lonjakan data secara efisien.', 51, 4, NULL, '2024-10-10 16:54:42', '2024-10-10 16:54:42'),
(251, 'text', 'Mengadakan pelatihan khusus bagi tim IT tentang cara mengoptimalkan penggunaan infrastruktur yang ada untuk meningkatkan performa sistem.', 51, 2, NULL, '2024-10-10 16:54:42', '2024-10-10 16:54:42'),
(252, 'text', 'Menerapkan teknologi load balancing untuk mendistribusikan lalu lintas data ke beberapa server agar dapat mengurangi beban pada server utama.', 51, 5, NULL, '2024-10-10 16:54:42', '2024-10-10 16:54:42'),
(253, 'text', 'Mengaktifkan sistem monitoring real-time untuk memantau penggunaan server dan mendeteksi potensi gangguan sebelum terjadi masalah serius.', 51, 3, NULL, '2024-10-10 16:54:42', '2024-10-10 16:54:42'),
(254, 'text', 'Menggunakan layanan pihak ketiga untuk menyediakan backup server yang hanya diaktifkan ketika lalu lintas data mencapai batas maksimum.', 51, 1, NULL, '2024-10-10 16:54:42', '2024-10-10 16:54:42'),
(255, 'text', 'A. Mengadakan konsultasi publik untuk menjaring aspirasi masyarakat sebelum menyusun undangundang.', 52, 5, NULL, '2024-10-10 16:55:13', '2024-10-10 16:55:13'),
(256, 'text', 'B. Menjalin kerja sama dengan lembaga internasional dalam merumuskan undang-undang.', 52, 0, NULL, '2024-10-10 16:55:13', '2024-10-10 16:55:13'),
(257, 'text', 'C. Mengawasi pelaksanaan undang-undang untuk memastikan kepatuhan terhadap aturan yang ada.', 52, 0, NULL, '2024-10-10 16:55:13', '2024-10-10 16:55:13'),
(258, 'text', 'D. Mengambil keputusan secara cepat untuk menanggapi perubahan situasi politik.', 52, 0, NULL, '2024-10-10 16:55:13', '2024-10-10 16:55:13'),
(259, 'text', 'E. Mengadakan diskusi internal yang melibatkan seluruh fraksi dalam DPR.', 52, 0, NULL, '2024-10-10 16:55:13', '2024-10-10 16:55:13'),
(260, 'text', 'Menyampaikan permohonan maaf kepada peserta, dan segera memperbaiki perangkat untuk melanjutkan presentasi.', 53, 3, NULL, '2024-10-10 16:56:12', '2024-10-10 16:56:12'),
(261, 'text', 'Menggunakan perangkat cadangan yang sudah dipersiapkan sebelumnya untuk melanjutkan seminar tanpa gangguan lebih lanjut.', 53, 5, NULL, '2024-10-10 16:56:12', '2024-10-10 16:56:12'),
(262, 'text', 'Menghubungi tim teknis untuk segera membantu memperbaiki masalah sambil tetap berkomunikasi dengan peserta.', 53, 4, NULL, '2024-10-10 16:56:12', '2024-10-10 16:56:12'),
(263, 'text', 'Menginformasikan kepada peserta bahwa ada masalah teknis dan memberikan instruksi membatalkan acara seminar .', 53, 1, NULL, '2024-10-10 16:56:12', '2024-10-10 16:56:12'),
(264, 'text', 'Menunda seminar dan mengatur ulang jadwal agar bisa dilaksanakan di lain waktu setelah masalah teknis diperbaiki.', 53, 2, NULL, '2024-10-10 16:56:12', '2024-10-10 16:56:12'),
(265, 'text', 'A. Mengawasi pelaksanaan hukum di seluruh wilayah Indonesia.', 54, 0, NULL, '2024-10-10 16:56:20', '2024-10-10 16:56:20'),
(266, 'text', 'B. Menyelesaikan sengketa hukum antara lembaga negara.', 54, 0, NULL, '2024-10-10 16:56:20', '2024-10-10 16:56:20'),
(267, 'text', 'C. Melakukan peninjauan kembali atas putusan pengadilan yang telah berkekuatan hukum tetap.', 54, 5, NULL, '2024-10-10 16:56:20', '2024-10-10 16:56:20'),
(268, 'text', 'D. Mengeluarkan putusan yang mengikat sebagai pedoman bagi peradilan di tingkat lebih rendah.', 54, 0, NULL, '2024-10-10 16:56:20', '2024-10-10 16:56:20'),
(269, 'text', 'E. Melakukan pengawasan terhadap pelaksanaan hukum di seluruh Indonesia.', 54, 0, NULL, '2024-10-10 16:56:20', '2024-10-10 16:56:20'),
(270, 'text', 'Meminta rekan kerja untuk meminjamkan perangkat yang lebih sesuai setiap kali ia mengalami kesulitan dalam menjalankan tugas.', 55, 2, NULL, '2024-10-10 16:57:12', '2024-10-10 16:57:12'),
(271, 'text', 'Menghubungi tim IT perusahaan untuk meminta bantuan sementara agar dapat menggunakan komputer perusahaan yang lebih mendukung.', 55, 4, NULL, '2024-10-10 16:57:12', '2024-10-10 16:57:12'),
(272, 'text', 'Membeli gadget baru dengan spesifikasi yang relevan dengan tuntutan pekerjaan untuk memastikan ia dapat bekerja secara optimal', 55, 5, NULL, '2024-10-10 16:57:12', '2024-10-10 16:57:12'),
(273, 'text', 'Menggunakan gadget yang ada dengan melakukan berbagai penyesuaian manual, meskipun membutuhkan lebih banyak waktu dan tenaga.', 55, 1, NULL, '2024-10-10 16:57:12', '2024-10-10 16:57:12'),
(274, 'text', 'Mengajukan permohonan kepada atasan untuk mendapatkan bantuan anggaran guna membeli perangkat yang lebih sesuai.', 55, 3, NULL, '2024-10-10 16:57:12', '2024-10-10 16:57:12'),
(275, 'text', 'A. Mengutamakan kesejahteraan rakyat dalam setiap kebijakan yang diambil.', 56, 0, NULL, '2024-10-10 16:57:14', '2024-10-10 16:57:14'),
(276, 'text', 'B. Memastikan bahwa setiap kebijakan mencerminkan prinsip-prinsip keadilan sosial.', 56, 0, NULL, '2024-10-10 16:57:14', '2024-10-10 16:57:14'),
(277, 'text', 'C. Mengintegrasikan nilai-nilai Pancasila dalam seluruh proses legislasi di DPR.', 56, 5, NULL, '2024-10-10 16:57:14', '2024-10-10 16:57:14'),
(278, 'text', 'D. Menjaga agar kebijakan pemerintah selaras dengan nilai-nilai Pancasila.', 56, 0, NULL, '2024-10-10 16:57:14', '2024-10-10 16:57:14'),
(279, 'text', 'E. Melibatkan masyarakat dalam perumusan kebijakan untuk menjaga aspirasi rakyat.', 56, 0, NULL, '2024-10-10 16:57:14', '2024-10-10 16:57:14'),
(280, 'text', 'Mendengarkan pendapat setiap orang dengan terbuka dan tidak memihak, dan memberikan pendapat secara sopan.', 57, 5, NULL, '2024-10-10 16:58:10', '2024-10-10 16:58:10'),
(281, 'text', 'Menyampaikan pendapatnya dengan sopan dan menghormati pandangan orang lain, meskipun berbeda dengan pandangannya.', 57, 4, NULL, '2024-10-10 16:58:10', '2024-10-10 16:58:10'),
(282, 'text', 'Menghindari perdebatan panjang jika situasi menjadi terlalu panas dan memberikan pandangan yang seimbang.', 57, 3, NULL, '2024-10-10 16:58:10', '2024-10-10 16:58:10'),
(283, 'text', 'Mengajak peserta forum untuk menerima pandangan mayoritas, agar perbedaan pandangan dapat dihindari.', 57, 2, NULL, '2024-10-10 16:58:10', '2024-10-10 16:58:10'),
(284, 'text', 'Memilih untuk tetap diam dan mendengarkan, agar tidak menimbulkan konflik lebih lanjut', 57, 1, NULL, '2024-10-10 16:58:10', '2024-10-10 16:58:10'),
(285, 'text', 'A. Mengambil keputusan yang menguntungkan seluruh tim, meskipun ada tekanan dari luar.', 58, 5, NULL, '2024-10-10 16:58:45', '2024-10-10 16:58:45'),
(286, 'text', 'B. Menjaga kerahasiaan informasi penting yang dipercayakan kepadanya.', 58, 0, NULL, '2024-10-10 16:58:45', '2024-10-10 16:58:45'),
(287, 'text', 'C. Mengutamakan kepentingan pribadi di atas kepentingan tim untuk mempertahankan posisinya.', 58, 0, NULL, '2024-10-10 16:58:45', '2024-10-10 16:58:45'),
(288, 'text', 'D. Menghindari keputusan sulit yang dapat merusak reputasinya.', 58, 0, NULL, '2024-10-10 16:58:45', '2024-10-10 16:58:45'),
(289, 'text', 'E. Menyembunyikan kesalahan yang dibuat untuk menjaga citra diri.', 58, 0, NULL, '2024-10-10 16:58:45', '2024-10-10 16:58:45'),
(290, 'text', 'A. Dengan menolak jabatan tinggi demi menjaga komitmennya terhadap rakyat.', 59, 5, NULL, '2024-10-10 17:00:01', '2024-10-10 17:00:01'),
(291, 'text', 'B. Dengan memanfaatkan kekayaannya untuk mendanai pergerakan kemerdekaan.', 59, 0, NULL, '2024-10-10 17:00:01', '2024-10-10 17:00:01'),
(292, 'text', 'C. Dengan menulis buku-buku tentang perjuangan dan integritas bangsa.', 59, 0, NULL, '2024-10-10 17:00:01', '2024-10-10 17:00:01'),
(293, 'text', 'D. Dengan bernegosiasi dengan pihak kolonial untuk mendapatkan otonomi.', 59, 0, NULL, '2024-10-10 17:00:01', '2024-10-10 17:00:01'),
(294, 'text', 'E. Dengan membimbing generasi muda untuk tetap berpegang pada nilai-nilai kebangsaan.', 59, 0, NULL, '2024-10-10 17:00:01', '2024-10-10 17:00:01'),
(295, 'text', 'A. Menyelesaikan tugas dengan cepat meskipun hasilnya tidak maksimal.', 60, 0, NULL, '2024-10-10 17:01:35', '2024-10-10 17:01:35'),
(296, 'text', 'B. Mengutamakan kepentingan tim dalam setiap keputusan yang diambil.', 60, 0, NULL, '2024-10-10 17:01:35', '2024-10-10 17:01:35'),
(297, 'text', 'C. Mengakui kesalahan yang dibuat dan mencari solusi untuk memperbaikinya.', 60, 5, NULL, '2024-10-10 17:01:35', '2024-10-10 17:01:35'),
(298, 'text', 'D. Mengambil kredit atas pekerjaan tim untuk meningkatkan reputasi diri.', 60, 0, NULL, '2024-10-10 17:01:35', '2024-10-10 17:01:35'),
(299, 'text', 'E. Menghindari tugas yang sulit untuk memastikan hasil yang tidak mengecewakan.', 60, 0, NULL, '2024-10-10 17:01:35', '2024-10-10 17:01:35'),
(300, 'text', 'A. Mengakui kesalahan yang telah dilakukan dan bertanggung jawab atas konsekuensinya.', 61, 5, NULL, '2024-10-10 17:02:20', '2024-10-10 17:02:20'),
(301, 'text', 'B. Membuat keputusan yang disukai oleh semua orang untuk menjaga reputasinya.', 61, 0, NULL, '2024-10-10 17:02:20', '2024-10-10 17:02:20'),
(302, 'text', 'C. Mempertahankan citra diri dengan tidak mengungkapkan kelemahannya.', 61, 0, NULL, '2024-10-10 17:02:20', '2024-10-10 17:02:20'),
(303, 'text', 'D. Menghindari situasi yang sulit agar tidak melakukan kesalahan.', 61, 0, NULL, '2024-10-10 17:02:20', '2024-10-10 17:02:20'),
(304, 'text', 'E. Menyalahkan orang lain ketika terjadi masalah untuk melindungi diri.', 61, 0, NULL, '2024-10-10 17:02:20', '2024-10-10 17:02:20'),
(305, 'text', 'A. Konsisten dalam memperjuangkan nilai-nilai yang diyakini meskipun menghadapi tekanan politik.', 62, 5, NULL, '2024-10-10 17:02:59', '2024-10-10 17:02:59'),
(306, 'text', 'B. Mengubah pendirian sesuai dengan situasi untuk menjaga dukungan dari konstituen.', 62, 0, NULL, '2024-10-10 17:02:59', '2024-10-10 17:02:59'),
(307, 'text', 'C. Menempatkan kepentingan pribadi di atas kepentingan publik untuk menjaga karier politik.', 62, 0, NULL, '2024-10-10 17:02:59', '2024-10-10 17:02:59'),
(308, 'text', 'D. Menghindari kontroversi dengan tidak mengambil keputusan yang sulit.', 62, 0, NULL, '2024-10-10 17:02:59', '2024-10-10 17:02:59'),
(309, 'text', 'E. Menyembunyikan kesalahan yang telah dilakukan untuk menjaga citra diri.', 62, 0, NULL, '2024-10-10 17:02:59', '2024-10-10 17:02:59'),
(310, 'text', 'A. Mengabaikan isu-isu lokal dan fokus pada masalah internasional.', 63, 0, NULL, '2024-10-10 17:03:43', '2024-10-10 17:03:43'),
(311, 'text', 'B. Aktif dalam kegiatan sosial yang membantu memperkuat solidaritas masyarakat.', 63, 5, NULL, '2024-10-10 17:03:43', '2024-10-10 17:03:43'),
(312, 'text', 'C. Mendukung proyek-proyek yang didanai oleh organisasi asing.', 63, 0, NULL, '2024-10-10 17:03:43', '2024-10-10 17:03:43'),
(313, 'text', 'D. Menghindari keterlibatan dalam kegiatan lokal demi kesibukan pribadi.', 63, 0, NULL, '2024-10-10 17:03:43', '2024-10-10 17:03:43'),
(314, 'text', 'E. Mengandalkan pemerintah untuk menangani semua masalah komunitas.', 63, 0, NULL, '2024-10-10 17:03:43', '2024-10-10 17:03:43'),
(315, 'text', 'A. Mengurangi penggunaan plastik sekali pakai dalam kehidupan sehari-hari.', 64, 5, NULL, '2024-10-10 17:04:35', '2024-10-10 17:04:35'),
(316, 'text', 'B. Mengabaikan masalah lingkungan karena dampaknya tidak langsung terlihat.', 64, 0, NULL, '2024-10-10 17:04:35', '2024-10-10 17:04:35'),
(317, 'text', 'C. Mengandalkan pemerintah untuk menangani semua masalah lingkungan.', 64, 0, NULL, '2024-10-10 17:04:35', '2024-10-10 17:04:35');
INSERT INTO `course_answers` (`id`, `type`, `answer`, `course_question_id`, `score`, `deleted_at`, `created_at`, `updated_at`) VALUES
(318, 'text', 'D. Membakar sampah plastik untuk mengurangi volume sampah.', 64, 0, NULL, '2024-10-10 17:04:35', '2024-10-10 17:04:35'),
(319, 'text', 'E. Menggunakan bahan kimia berbahaya untuk mempercepat produksi.', 64, 0, NULL, '2024-10-10 17:04:35', '2024-10-10 17:04:35'),
(320, 'text', 'A. Memberikan fasilitas lebih kepada daerah yang sudah maju.', 65, 0, NULL, '2024-10-10 17:05:24', '2024-10-10 17:05:24'),
(321, 'text', 'B. Mengabaikan kebutuhan daerah terpencil demi efisiensi anggaran.', 65, 0, NULL, '2024-10-10 17:05:24', '2024-10-10 17:05:24'),
(322, 'text', 'C. Mengalokasikan anggaran pembangunan secara merata ke seluruh wilayah.', 65, 5, NULL, '2024-10-10 17:05:24', '2024-10-10 17:05:24'),
(323, 'text', 'D. Menerapkan kebijakan yang hanya menguntungkan kelompok mayoritas.', 65, 0, NULL, '2024-10-10 17:05:24', '2024-10-10 17:05:24'),
(324, 'text', 'E. Mengurangi anggaran untuk sektor yang dianggap tidak menguntungkan.', 65, 0, NULL, '2024-10-10 17:05:24', '2024-10-10 17:05:24'),
(325, 'text', 'A. Mengutamakan kepentingan pribadi meskipun bertentangan dengan kebijakan perusahaan.', 66, 0, NULL, '2024-10-10 17:06:06', '2024-10-10 17:06:06'),
(326, 'text', 'B. Menyelesaikan pekerjaan dengan baik sesuai dengan pedoman dan etika perusahaan.', 66, 5, NULL, '2024-10-10 17:06:06', '2024-10-10 17:06:06'),
(327, 'text', 'C. Menghindari pekerjaan yang sulit untuk memastikan hasil yang memuaskan.', 66, 0, NULL, '2024-10-10 17:06:06', '2024-10-10 17:06:06'),
(328, 'text', 'D. Menyembunyikan kesalahan untuk menjaga reputasi pribadi.', 66, 0, NULL, '2024-10-10 17:06:06', '2024-10-10 17:06:06'),
(329, 'text', 'E. Mengambil keuntungan dari kelemahan sistem untuk kepentingan pribadi.', 66, 0, NULL, '2024-10-10 17:06:06', '2024-10-10 17:06:06'),
(330, 'text', 'A. Menolak sepenuhnya pengaruh budaya asing untuk menjaga kemurnian budaya lokal.', 67, 0, NULL, '2024-10-10 17:06:59', '2024-10-10 17:06:59'),
(331, 'text', 'B. Menggabungkan elemen budaya asing ke dalam budaya lokal untuk memperkaya identitas nasional.', 67, 0, NULL, '2024-10-10 17:06:59', '2024-10-10 17:06:59'),
(332, 'text', 'C. Mempromosikan budaya lokal secara aktif melalui festival dan acara internasional.', 67, 5, NULL, '2024-10-10 17:06:59', '2024-10-10 17:06:59'),
(333, 'text', 'D. Mengisolasi budaya lokal dari dunia luar untuk mencegah perubahan.', 67, 0, NULL, '2024-10-10 17:06:59', '2024-10-10 17:06:59'),
(334, 'text', 'E. Mengadopsi budaya asing yang lebih modern dan meninggalkan tradisi lama.', 67, 0, NULL, '2024-10-10 17:06:59', '2024-10-10 17:06:59'),
(335, 'text', 'A. Mengajarkan siswa untuk fokus pada prestasi akademik internasional.', 68, 0, NULL, '2024-10-10 17:07:53', '2024-10-10 17:07:53'),
(336, 'text', 'B. Meningkatkan pemahaman siswa tentang sejarah dan budaya Indonesia.', 68, 5, NULL, '2024-10-10 17:07:53', '2024-10-10 17:07:53'),
(337, 'text', 'C. Mengabaikan pendidikan kebangsaan demi fokus pada mata pelajaran sains dan teknologi.', 68, 0, NULL, '2024-10-10 17:07:53', '2024-10-10 17:07:53'),
(338, 'text', 'D. Mendorong siswa untuk meninggalkan budaya lokal demi mengikuti tren global.', 68, 0, NULL, '2024-10-10 17:07:53', '2024-10-10 17:07:53'),
(339, 'text', 'E. Membatasi akses siswa pada informasi tentang dunia luar untuk menjaga nasionalisme.', 68, 0, NULL, '2024-10-10 17:07:53', '2024-10-10 17:07:53'),
(340, 'text', 'A. Di depan rumah, terdapat Taman kecil yang penuh dengan bunga.', 69, 0, NULL, '2024-10-10 17:08:47', '2024-10-10 17:08:47'),
(341, 'text', 'B. Setiap pagi, Ayah membaca Koran sambil menikmati kopi.', 69, 0, NULL, '2024-10-10 17:08:47', '2024-10-10 17:08:47'),
(342, 'text', 'C. Kami akan pergi ke taman mini Indonesia Indah akhir pekan ini.', 69, 0, NULL, '2024-10-10 17:08:47', '2024-10-10 17:08:47'),
(343, 'text', 'D. Paman menyelesaikan studi di Institut Teknologi Bandung.', 69, 5, NULL, '2024-10-10 17:08:47', '2024-10-10 17:08:47'),
(344, 'text', 'E. Adik sedang bermain dengan temannya di Halaman rumah.', 69, 0, NULL, '2024-10-10 17:08:47', '2024-10-10 17:08:47'),
(345, 'text', 'Kami berencana mengunjungi museum Nasional dan universitas Gadjah Mada pada liburan ini.', 70, 0, NULL, '2024-10-11 00:11:13', '2024-10-11 00:11:13'),
(346, 'text', 'Kami berencana mengunjungi Museum Nasional dan Universitas Gadjah Mada pada liburan ini.', 70, 0, NULL, '2024-10-11 00:11:13', '2024-10-11 00:11:13'),
(347, 'text', 'Kami berencana mengunjungi museum nasional dan Universitas Gadjah Mada pada liburan ini.', 70, 5, NULL, '2024-10-11 00:11:13', '2024-10-11 00:11:13'),
(348, 'text', 'Kami berencana mengunjungi Museum nasional dan universitas gadjah Mada pada liburan ini.', 70, 0, NULL, '2024-10-11 00:11:13', '2024-10-11 00:11:13'),
(349, 'text', '. Kami berencana mengunjungi Museum Nasional dan universitas gadjah Mada pada liburan ini.', 70, 0, NULL, '2024-10-11 00:11:13', '2024-10-11 00:11:13'),
(350, 'text', 'Keuletan dalam menjaga tradisi yang hampir punah.', 71, 0, NULL, '2024-10-11 00:12:17', '2024-10-11 00:12:17'),
(351, 'text', 'Kecintaan yang mendalam terhadap karya seni yang ia geluti.', 71, 0, NULL, '2024-10-11 00:12:17', '2024-10-11 00:12:17'),
(352, 'text', 'Ketekunan yang tak pernah surut meski usia terus bertambah.', 71, 5, NULL, '2024-10-11 00:12:17', '2024-10-11 00:12:17'),
(353, 'text', 'Dedikasi untuk menciptakan keindahan dalam setiap helai benang.', 71, 0, NULL, '2024-10-11 00:12:17', '2024-10-11 00:12:17'),
(354, 'text', 'Kesabaran dalam menyelesaikan setiap detail dengan sempurna.', 71, 0, NULL, '2024-10-11 00:12:17', '2024-10-11 00:12:17'),
(355, 'text', 'Pentingnya pengetahuan akademis dalam pendidikan karakter.', 72, 0, NULL, '2024-10-11 00:13:36', '2024-10-11 00:13:36'),
(356, 'text', 'Pendidikan karakter lebih penting daripada pendidikan akademis.', 72, 0, NULL, '2024-10-11 00:13:36', '2024-10-11 00:13:36'),
(357, 'text', 'Sekolah dan keluarga memiliki tanggung jawab dalam membentuk karakter anak.', 72, 5, NULL, '2024-10-11 00:13:36', '2024-10-11 00:13:36'),
(358, 'text', 'Pendidikan karakter mencakup pengetahuan akademis, moral, dan sosial.', 72, 0, NULL, '2024-10-11 00:13:36', '2024-10-11 00:13:36'),
(359, 'text', 'Generasi muda harus mendapatkan pendidikan karakter yang baik.', 72, 0, NULL, '2024-10-11 00:13:36', '2024-10-11 00:13:36'),
