(465, 'text', 'Seluruh siswa kelas 12 adalah calon mahasiswa kampus terkenal', 94, 0, NULL, '2024-10-11 01:12:32', '2024-10-11 01:12:32'),
(466, 'text', 'Budi merupakan seorang tentara angkatan tahun 2020', 94, 0, NULL, '2024-10-11 01:12:32', '2024-10-11 01:12:32'),
(467, 'text', 'Keluarga perempuan itu datang pagi tadi', 94, 0, NULL, '2024-10-11 01:12:32', '2024-10-11 01:12:32'),
(468, 'text', 'Susi memberikan kartu nama di acara ulang tahun perusahaan', 94, 5, NULL, '2024-10-11 01:12:32', '2024-10-11 06:10:55'),
(469, 'text', 'Saya terjatuh di depan kelas A', 94, 0, NULL, '2024-10-11 01:12:32', '2024-10-11 01:12:32'),
(470, 'text', 'Semua siwa di kelas A mendapatkan bimbingan belajar tambahan.', 95, 0, NULL, '2024-10-11 01:15:44', '2024-10-11 01:15:44'),
(471, 'text', 'Tidak ada siswa di kelas A yang mendapatkan bimbingan belajar tambahan.', 95, 0, NULL, '2024-10-11 01:15:44', '2024-10-11 01:15:44'),
(472, 'text', 'Beberapa siswa di kelas A mengikuti program beasiswa.', 95, 0, NULL, '2024-10-11 01:15:44', '2024-10-11 01:15:44'),
(473, 'text', 'Tidak semua siswa di kelas A mendapatkan bimbingan belajar tambahan.', 95, 0, NULL, '2024-10-11 01:15:44', '2024-10-11 01:15:44'),
(474, 'text', 'Semua siswa di kelas A mungkin tidak mendapatkan bimbingan belajar tambahan.', 95, 5, NULL, '2024-10-11 01:15:44', '2024-10-11 06:11:04'),
(475, 'text', 'Aris memiliki kualitas tidur yang tidak baik atau pola tidur yang teratur', 96, 0, NULL, '2024-10-11 01:19:44', '2024-10-11 01:19:44'),
(476, 'text', 'Aris memiliki pola tidur yang tidak teratur dan kualitas tidur yang tidak baik.', 96, 0, NULL, '2024-10-11 01:19:44', '2024-10-11 01:19:44'),
(477, 'text', 'Aris memiliki pola tidur yang teratur atau kualitas tidurnya tidak baik.', 96, 5, NULL, '2024-10-11 01:19:44', '2024-10-11 06:11:27'),
(478, 'text', 'Aris memiliki kualitas tidur yang baik, tetapi pola tidurnya tidak teratur', 96, 0, NULL, '2024-10-11 01:19:44', '2024-10-11 01:19:44'),
(479, 'text', 'Aris memilik pola tidur yang teratur, tetapi kualitas tidurnya tidak baik.', 96, 0, NULL, '2024-10-11 01:19:44', '2024-10-11 01:19:44'),
