(535, 'text', 'A.	melakukan protes keras terhadap pernyataan kepala suku yang dianggap radikal', 109, 4, NULL, '2024-10-11 05:47:25', '2024-10-11 05:47:25'),
(536, 'text', 'B.	meninggalkan kerumunan dengan diam-diam karena pernyataan kepala suku mengarah kepada Tindakan radikalisme', 109, 1, NULL, '2024-10-11 05:47:25', '2024-10-11 05:47:25'),
(537, 'text', 'C.	mendengarkan saja kemudian tak memperdulikan arahan dan pernyataanya sebagai bentuk penghormatan kepada kepala suku', 109, 2, NULL, '2024-10-11 05:47:25', '2024-10-11 05:47:25'),
(538, 'text', 'D.	melakukan aktivitas lain yang menunjukkan sikap kurang respect terhadap pernyataan kepala suku yang mengarah pada Tindakan radikalisme', 109, 3, NULL, '2024-10-11 05:47:25', '2024-10-11 05:47:25'),
(539, 'text', 'E.	merekam lalu melaporkan hal tersebut kepada pemerintah setempat untuk kemudian dilakukan pengawasan terhadap pernyataan-pernyataan dan Tindakan kepala suku', 109, 5, NULL, '2024-10-11 05:47:25', '2024-10-11 05:47:25'),
(540, 'text', 'A.	Melakukan pengawasan terhadap pemustaka yang membaca buku tersebut sebagai bagian dari kewaspadaan terhadap segala bentuk Tindakan radikalisme', 110, 4, NULL, '2024-10-11 05:48:15', '2024-10-11 05:48:15'),
(541, 'text', 'B.	Memasukkan buku itu ke dalam kategori buku yang hanya boleh dibaca di tempat agar tidak berpotensi diperbanyak oleh oknum-oknum tertentu', 110, 3, NULL, '2024-10-11 05:48:15', '2024-10-11 05:48:15'),
(542, 'text', 'C.	Menyembunyikan buku tersebut namun masih di dalam area perpustakaan', 110, 1, NULL, '2024-10-11 05:48:15', '2024-10-11 05:48:15'),
(543, 'text', 'D.	Menjelaskan kepada pemustaka bahwa buku tersebut berbahaya untuk dibaca tanpa bimbingan', 110, 5, NULL, '2024-10-11 05:48:15', '2024-10-11 05:48:15'),
(544, 'text', 'E.	Tetap memperlakukan buku tersebut seperti buku-buku lainnya karena telah memperoleh izin dari kepala perpustkaan', 110, 2, NULL, '2024-10-11 05:48:15', '2024-10-11 05:48:15'),
(545, 'text', 'A.	Menanamkan pentingnya nilai persatuan dan kesatuan dengan cara yang sederhana seperti permainan, kerja bakti dan lainnya', 111, 5, NULL, '2024-10-11 05:49:18', '2024-10-11 05:49:18'),
(546, 'text', 'B.	Mengajarkan pentingnya toleransi dan tenggang rasa kepada seluruh anak-anak di dalam kelas', 111, 4, NULL, '2024-10-11 05:49:18', '2024-10-11 05:49:18'),
(547, 'text', 'C.	Menambah jam kegiatan belajar mengajar untuk amta pelajaran Pendidikan Pancasila', 111, 1, NULL, '2024-10-11 05:49:18', '2024-10-11 05:49:18'),
(548, 'text', 'D.	menerapkan sistem reward kepada anak-anak SD agar nilai Pancasila dapat diserap dengan baik', 111, 2, NULL, '2024-10-11 05:49:18', '2024-10-11 05:49:18'),
(549, 'text', 'E.	mengajak orang tua murid untuk ikut serta mendidik putra-putrinya dengan nilai-nilai Pancasila di rumah masing-masing karena peran keluarga juga sangat penting', 111, 3, NULL, '2024-10-11 05:49:18', '2024-10-11 05:49:18'),
(550, 'text', 'A.	Mengusulkan agar perusahaan tidak terburu-buru mencari karyawab yang diduga terpapar paham radikalisme, karena bisa saja isu tersebut hoax', 112, 4, NULL, '2024-10-11 05:50:03', '2024-10-11 05:50:03'),
(551, 'text', 'B.	Memberikan usulan agar perusahaan memeriksa terlebih dahulu kebenaran laporan tersebut, baru kemudian mengambil Tindakan yang tepat', 112, 5, NULL, '2024-10-11 05:50:03', '2024-10-11 05:50:03'),
(552, 'text', 'C.	Mengusulkan agar mencari karyawan yang terpapar radikal tersebut, kemudian melaporkan ke pihak yang berwenang mengatasi masalah tersebut', 112, 3, NULL, '2024-10-11 05:50:03', '2024-10-11 05:50:03'),
(553, 'text', 'D.	Mengusulkan adanya jadwal rutin siraman rohani untuk semua karyawan agar mereka tidak terpapar paham radikalisme', 112, 1, NULL, '2024-10-11 05:50:03', '2024-10-11 05:50:03'),
(554, 'text', 'E.	Memberikan usulan agar jika isu karyawan yang terpapar radikal itu terbukti, perusahaan harus segera memberhentikan karyawan tersebut tanpa melihat seberapa tinggi jabatannya', 112, 2, NULL, '2024-10-11 05:50:03', '2024-10-11 05:50:03'),
(555, 'text', 'A.	Melaporkan kepada atasan dan direktur di kantor agar rekan kerja tersebut dipanggil', 113, 4, NULL, '2024-10-11 05:50:45', '2024-10-11 05:50:45'),
(556, 'text', 'B.	Melaporkan kepada atasan di kantor agar rekan kerja tersebut diberikan pembinaan ideologi', 113, 5, NULL, '2024-10-11 05:50:45', '2024-10-11 05:50:45'),
(557, 'text', 'C.	Mendukung rekan kerja anda karena menyanyikan dan berdiri saat lagu kebangsaaan adalah thogut', 113, 1, NULL, '2024-10-11 05:50:45', '2024-10-11 05:50:45'),
(558, 'text', 'D.	Mendiamkan saja karena hal tersebut merupakan kebebasan berespresi', 113, 2, NULL, '2024-10-11 05:50:45', '2024-10-11 05:50:45'),
(559, 'text', 'E.	Langsung menelepon pihak berwajib', 113, 3, NULL, '2024-10-11 05:50:45', '2024-10-11 05:50:45'),
(560, 'text', 'A.	Merapatkan dengan pimpinan perusahaan untuk membahas mengenai Tindakan yang sebaiknya dilakukan untuk menangkal paham ektrimisme', 114, 3, NULL, '2024-10-11 05:51:29', '2024-10-11 05:51:29'),
(561, 'text', 'B.	Mengajak staf tersebut untuk berbicara secara personal agar mempertanggungjawabkan perbuatannya', 114, 1, NULL, '2024-10-11 05:51:29', '2024-10-11 05:51:29'),
(562, 'text', 'C.	Mengajak staf tersebut untuk berbicara secara personal dan menanyakan mengenai informasi yang anda peroleh agar mendapat klarifikasi', 114, 5, NULL, '2024-10-11 05:51:29', '2024-10-11 05:51:29'),
(563, 'text', 'D.	Memberlakukan aturan yang ketat agar tidak ada ruang untuk paham ekstrimisme di bidang anda', 114, 2, NULL, '2024-10-11 05:51:29', '2024-10-11 05:51:29'),
(564, 'text', 'E.	Melaporkan kepada pimpinan perusahaan agar kecurigaan anda dapat ditelusuri dan ditindaklanjuti', 114, 4, NULL, '2024-10-11 05:51:29', '2024-10-11 05:51:29'),
(565, 'text', 'A.	Menerima tugas dari atasan tersebut dengan senang hati dan meminta bantuan atasan untuk memilih anggota tim khusus untuk menangani kasus terorisme tersebut', 115, 2, NULL, '2024-10-11 05:52:23', '2024-10-11 05:52:23'),
(566, 'text', 'B.	Menerima Amanah dari atasan dengan penuh tanggung jawab dan segera menentukan anggota tim khusus untuk menangani kasus terorisme tersebut', 115, 4, NULL, '2024-10-11 05:52:23', '2024-10-11 05:52:23'),
(567, 'text', 'C.	Menjalankan Amanah dari atasan dengan penuh integritas serta professional dalam menentukan anggota tim khusus yang menangani aksi terorisme tersebut', 115, 3, NULL, '2024-10-11 05:52:23', '2024-10-11 05:52:23'),
(568, 'text', 'D.	Melaksanakan tugas dari atasan dengan penuh integritas dan segera membentuk dan menentukan anggota tim khusus yang menangani kasus terorisme tersebut', 115, 5, NULL, '2024-10-11 05:52:23', '2024-10-11 05:52:23'),
(569, 'text', 'E.	Melaksanakan Amanah dari atasan dengan penuh tanggung jawab kemudian membentuk tim khusus dengan mempertimbangkan usulan rekan kerja dalam menangani kasus terosisme yang terjadi', 115, 1, NULL, '2024-10-11 05:52:23', '2024-10-11 05:52:23'),
(570, 'text', 'A.	Membiarkan saja hal tersebut agar tidak terjadi keributan', 116, 1, NULL, '2024-10-11 05:53:15', '2024-10-11 05:53:15'),
(571, 'text', 'B.	Mendatangi siswa tersebut dan menegurnya dengan keras agar dia jera', 116, 4, NULL, '2024-10-11 05:53:15', '2024-10-11 05:53:15'),
(572, 'text', 'C.	Mendatangi siswa tersebut dan menegurnya dengan tegas agar dia tidak mengulangi lagi perbuatannya', 116, 5, NULL, '2024-10-11 05:53:15', '2024-10-11 05:53:15'),
(573, 'text', 'D.	Langsung mengeluarkan siswa tersebut dari kelas', 116, 2, NULL, '2024-10-11 05:53:15', '2024-10-11 05:53:15'),
(574, 'text', 'E.	Mendatangi siswa yang diolok-olok tersebut setelah kelas selesai dan menghiburnya', 116, 3, NULL, '2024-10-11 05:53:15', '2024-10-11 05:53:15'),
(575, 'text', 'A.	Setiap orang bebas dan berhak menyampaikan pendapatnya, karena hal tersebut dilindungi oleh UU', 117, 2, NULL, '2024-10-11 05:54:13', '2024-10-11 05:54:13'),
(576, 'text', 'B.	Menegur rekan kerja anda dengan segera untuk mengahapus postingan tersebut karena dapat memicu konflik dan perpecahan', 117, 5, NULL, '2024-10-11 05:54:13', '2024-10-11 05:54:13'),
(577, 'text', 'C.	Melaporkan postingan rekan kerja anda melalui whistleblowing system agar diberikan hukuman disiplin', 117, 3, NULL, '2024-10-11 05:54:13', '2024-10-11 05:54:13'),
(578, 'text', 'D.	Mengigatkan dengan baik akan hak dan kewajiban sebagai ASN melalui whatsaap', 117, 4, NULL, '2024-10-11 05:54:13', '2024-10-11 05:54:13'),
(579, 'text', 'E.	Membiarkan saja karena pandangan politik seseorang tidak bisa di intervensi', 117, 1, NULL, '2024-10-11 05:54:13', '2024-10-11 05:54:13'),
(580, 'text', 'A.	Berusaha menjelaskan kepada kelompok tersebut untuk bisa menghormati warga sekitar', 118, 2, NULL, '2024-10-11 05:57:52', '2024-10-11 05:57:52'),
(581, 'text', 'B.	Memberikan pengertian bahwa Tindakan kelompok tersebut dapat menggangu kenyamanan warga', 118, 3, NULL, '2024-10-11 05:57:52', '2024-10-11 05:57:52'),
(582, 'text', 'C.	Aktif berdiskusi dengan tetangga lain mengenai keadaan di lingkungan tersebut', 118, 4, NULL, '2024-10-11 05:57:52', '2024-10-11 05:57:52'),
(583, 'text', 'D.	Berdiam diri saja seakan-akan tidak terjadi apa-apa', 118, 1, NULL, '2024-10-11 05:57:52', '2024-10-11 05:57:52'),
(584, 'text', 'E.	Bertanya kepada RT setempat mengenai kebiasaan di lingkungan tersebut', 118, 5, NULL, '2024-10-11 05:57:52', '2024-10-11 05:57:52'),
(585, 'text', 'A.	Memberikan informasi keberadaan sahabat anda, walaupun hati anda terasa berat mengatakannya', 119, 4, NULL, '2024-10-11 05:58:31', '2024-10-11 05:58:31'),
(586, 'text', 'B.	Memberikan informasi keberadaan sahabat anda, agar sahabat anda menyadari bahwa perilakunya salah', 119, 5, NULL, '2024-10-11 05:58:31', '2024-10-11 05:58:31'),
(587, 'text', 'C.	Tidak memberikan informasi keberadaan sahabat anda, karena ingin menjaga hubungan baik persahabatan anda', 119, 1, NULL, '2024-10-11 05:58:31', '2024-10-11 05:58:31'),
(588, 'text', 'D.	Tidak memberikan informasi keberadaan sahabat anda, karena ingin menyadarkan sahabat anda sendiri', 119, 2, NULL, '2024-10-11 05:58:31', '2024-10-11 05:58:31'),
(589, 'text', 'E.	Memberikan informasi keberadaan sahabat anda dengan terpaksa', 119, 3, NULL, '2024-10-11 05:58:31', '2024-10-11 05:58:31'),
(590, 'text', 'A.	akan memfasilitasi tempat untuk beribadah mereka di lingkungan bekerja', 120, 3, NULL, '2024-10-11 05:59:11', '2024-10-11 05:59:11'),
(591, 'text', 'B.	mendiskusikan hal ini dengan jajaran pimpinan untuk dicarikan solusinya', 120, 2, NULL, '2024-10-11 05:59:11', '2024-10-11 05:59:11'),
(592, 'text', 'C.	menerima aturan tersebut dan ikut mematuhinya', 120, 1, NULL, '2024-10-11 05:59:11', '2024-10-11 05:59:11'),
(593, 'text', 'D.	memberikan kebijakan yang bersifat toleran kepada pekerja yang muslim untuk beribadah', 120, 4, NULL, '2024-10-11 05:59:11', '2024-10-11 05:59:11'),
(594, 'text', 'E.	bersifat toleran dan menyediakan fasilitas ibadah pekerjaan', 120, 5, NULL, '2024-10-11 05:59:11', '2024-10-11 05:59:11'),
(595, 'text', 'A.	Menumbuhkan toleransi antar suku', 121, 4, NULL, '2024-10-11 06:00:17', '2024-10-11 06:00:17'),
(596, 'text', 'B.	Melakukan penyuluhan kepada kedua suku', 121, 2, NULL, '2024-10-11 06:00:17', '2024-10-11 06:00:17'),
(597, 'text', 'C.	Memerintah aparat untuk mengamankan keduanya', 121, 3, NULL, '2024-10-11 06:00:17', '2024-10-11 06:00:17'),
(598, 'text', 'D.	Memberikan vonis terhadap kedua suku sehingga mereka menyadari akan pentingnya hidup dalam kebhinekaaan', 121, 1, NULL, '2024-10-11 06:00:17', '2024-10-11 06:00:17'),
(599, 'text', 'E.	Mengadakan rekonsiliasi antar suku', 121, 5, NULL, '2024-10-11 06:00:17', '2024-10-11 06:00:17'),
(600, 'text', 'A.	Menyadarkan warga mengenai keberagaman agama sebagai suatu hal yang tidak perlu dipermasalahkan dan memberi tahu warga baru untuk membatasi kegiatan keagaman di desa', 122, 3, NULL, '2024-10-11 06:01:07', '2024-10-11 06:01:07'),
(601, 'text', 'B.	Menyadarkan warga mengenai keberagaman agama sebagai suatu hal yang tidak perlu dipermasalahkan dan memberikan kebebasan kepada warga baru untuk melakukan kegiatan keagamaan', 122, 5, NULL, '2024-10-11 06:01:07', '2024-10-11 06:01:07'),
(602, 'text', 'C.	menyadarkan warga mengenai keberagaman agama sebagai suatu hal yang tidak perlu dipermasalahkan dan memberi tahu warga baru untuk tidak melakukan kegiatan keagamaan di desa', 122, 2, NULL, '2024-10-11 06:01:07', '2024-10-11 06:01:07'),
(603, 'text', 'D.	menerima usulan warga dan memberi tahu warga batu dengan sopan untuk tidak melakukan kegiatan keagamaan', 122, 1, NULL, '2024-10-11 06:01:07', '2024-10-11 06:01:07'),
(604, 'text', 'E.	menolak usulan warga dan tetap memberikan kebebasan kepada warga baru untuk melakukan kegiatan keagamaan di desa karna itu adalah haknya sebagai warga negara', 122, 4, NULL, '2024-10-11 06:01:07', '2024-10-11 06:01:07'),
(605, 'text', 'A.	Tidak membelikan smartphone hingga anak anda berusia 18 tahun', 123, 1, NULL, '2024-10-11 06:01:47', '2024-10-11 06:01:47'),
(606, 'text', 'B.	Menanamkan semangat kebangsaan dan toleransi', 123, 4, NULL, '2024-10-11 06:01:47', '2024-10-11 06:01:47'),
(607, 'text', 'C.	Selektif dalam memilihkan teman bermain kepada anak anda', 123, 2, NULL, '2024-10-11 06:01:47', '2024-10-11 06:01:47'),
(608, 'text', 'D.	Membatasi fitur smartphone anak anda agar tidak mengakses konten radikal', 123, 3, NULL, '2024-10-11 06:01:47', '2024-10-11 06:01:47'),
(609, 'text', 'E.	Memberikan pemahaman agama yang baik dan benar secara moderat dan damai', 123, 5, NULL, '2024-10-11 06:01:47', '2024-10-11 06:01:47'),
(610, 'text', 'A.	Mempertemukan warga A dan B dalam forum untuk menyelesaikan permasalahan tersebut', 124, 5, NULL, '2024-10-11 06:02:31', '2024-10-11 06:02:31'),
(611, 'text', 'B.	Menunggu ketua RT Kembali untuk menyelesaikan konflik tersebut', 124, 1, NULL, '2024-10-11 06:02:31', '2024-10-11 06:02:31'),
(612, 'text', 'C.	Menasehati warga A agar menyetel music tidak terlalu keras', 124, 4, NULL, '2024-10-11 06:02:31', '2024-10-11 06:02:31'),
(613, 'text', 'D.	Meminta saran dari para warga untuk menindaklanjuti penyelesaian konflik', 124, 3, NULL, '2024-10-11 06:02:31', '2024-10-11 06:02:31'),
(614, 'text', 'E.	Ikut menyalahkan warga A karena bertindak tidak menghargai warga lain', 124, 2, NULL, '2024-10-11 06:02:31', '2024-10-11 06:02:31'),
(615, 'text', 'A.	Menyadarkan tetangga sekitar agar memberikan kesempatan kepada keluarga tersebut untuk tinggal dengan tenang dan nyaman di lingkungan', 125, 4, NULL, '2024-10-11 06:03:11', '2024-10-11 06:03:11'),
(616, 'text', 'B.	Menyadarkan keluarga lainnya mengenai ragamnya agama di Indonesia dan hal tersebut tidak perlu diganggu-gugat', 125, 5, NULL, '2024-10-11 06:03:11', '2024-10-11 06:03:11'),
(617, 'text', 'C.	Menerima keluarga tersebut dengan mengadakan pertemuan dengan warga lain dan anda menyatakan kekecewaan anda karena hidup di tengah masyarakat yang rasisme', 125, 2, NULL, '2024-10-11 06:03:11', '2024-10-11 06:03:11'),
(618, 'text', 'D.	Menyadarkan tetangga sekitar bahwa hidup dengan menerima segala bentuk keberagaman merupakan perbuatan yang dapat mengancam persatuan dan kesatuan', 125, 1, NULL, '2024-10-11 06:03:11', '2024-10-11 06:03:11'),
(619, 'text', 'E.	Menerima keluarga tersebut dikeluarga anda. Dan menyarankan agar bersabar dan menyarakan untuk tidak terbuka saat menjalankan kegiatan agamnya sehingga tidak dilihat oleh masyarakat lain', 125, 3, NULL, '2024-10-11 06:03:11', '2024-10-11 06:03:11'),
(620, 'text', 'A.	Pemerintah harusnya memberikan ruang untuk tokoh tersebut untuk membela dirinya', 126, 1, NULL, '2024-10-11 06:04:19', '2024-10-11 06:04:19'),
(621, 'text', 'B.	Kasus hukum harus diselesaikan di pengadilan. Bukan malah membuat drama di jalanan', 126, 5, NULL, '2024-10-11 06:04:19', '2024-10-11 06:04:19'),
(622, 'text', 'C.	Mendukung Tindakan tersebut asalkan tidak melanggar aturan', 126, 2, NULL, '2024-10-11 06:04:19', '2024-10-11 06:04:19'),
(623, 'text', 'D.	Pemerintah harus mengambil Tindakan tegas demi mengamankan ketertiban Bersama', 126, 4, NULL, '2024-10-11 06:04:19', '2024-10-11 06:04:19'),
(624, 'text', 'E.	Itu hal yang wajar mengigat hak dari setiap warga untuk mengemukan aspirasi di muka umum', 126, 3, NULL, '2024-10-11 06:04:19', '2024-10-11 06:04:19'),
