(629, 'text', 'E.	kerja keras', 127, 5, NULL, '2024-11-07 04:02:13', '2024-11-07 04:02:13'),
(630, 'text', 'A.	Merubah Haluan dukungan politik terhadap pihak yang didukung oleh negara-negara yang telah terjalin Kerjasama bilateral dengannya', 128, 0, NULL, '2024-11-07 04:02:52', '2024-11-07 04:02:52'),
(631, 'text', 'B.	Melakukan negoisasi internal terhadap negara-negara yang terjalin hubungan bilateral terkait masalah dukungan politik', 128, 0, NULL, '2024-11-07 04:02:52', '2024-11-07 04:02:52'),
(632, 'text', 'C.	Melakukan pendekatan politis dengan mengajak negara-negara yang terjalin hubungan politik untuk mendukung posisi palestina', 128, 0, NULL, '2024-11-07 04:02:52', '2024-11-07 04:02:52'),
(633, 'text', 'D.	Tidak mengambil keputusan politik dalam sidang PBB demi menjaga kestabilan ekonomi negara meski secara pribadi tetap mendukung palestina', 128, 0, NULL, '2024-11-07 04:02:52', '2024-11-07 04:02:52'),
(634, 'text', 'E.	Menyampaikan secara jelas keputusan politik dengan mendukung palestina, meski hal tersebut membahayakan perekonomian negara', 128, 5, NULL, '2024-11-07 04:02:52', '2024-11-07 04:02:52'),
(635, 'text', 'A.	Meminta kepada pihak negara tersebut untuk mengklarifikasi pernyataannya, kemudian memberikan bantuan', 129, 0, NULL, '2024-11-07 04:03:37', '2024-11-07 04:03:37'),
(636, 'text', 'B.	Melakukan diskusi terhadap pihak internal organisasi mengenai keputusan untuk memberi bantuan', 129, 0, NULL, '2024-11-07 04:03:37', '2024-11-07 04:03:37'),
(637, 'text', 'C.	Memberikan bantuan kemudian menyampaikan kepada media bahwa negara tersebut meminta bantuan ACT', 129, 0, NULL, '2024-11-07 04:03:37', '2024-11-07 04:03:37'),
(638, 'text', 'D.	Memberikan bantuan tanpa mempedulikan berita yang telah dibuat oleh negara tersebut', 129, 5, NULL, '2024-11-07 04:03:37', '2024-11-07 04:03:37'),
(639, 'text', 'E.	Memberikan bantuan dengan meminta media meliput kegiatannya sebagai bentuk klarifikasi terhadap berita yang beredar', 129, 0, NULL, '2024-11-07 04:03:37', '2024-11-07 04:03:37'),
(640, 'text', 'A.	Voting kedudukannya lebih tinggi daripada kemanfaatan', 130, 0, NULL, '2024-11-07 04:04:23', '2024-11-07 04:04:23'),
(641, 'text', 'B.	Kerja keras membuat usulan akan berimplikasi diterima usulan', 130, 0, NULL, '2024-11-07 04:04:23', '2024-11-07 04:04:23'),
(642, 'text', 'C.	Putusan musyawarah cenderung dimenangkan kewibawaan pengusul', 130, 0, NULL, '2024-11-07 04:04:23', '2024-11-07 04:04:23'),
(643, 'text', 'D.	Integritas terhadap putusan musyawarah walaupun usulannya ditolak demi kepentingan Bersama', 130, 5, NULL, '2024-11-07 04:04:23', '2024-11-07 04:04:23'),
(644, 'text', 'E.	Komitmen pada kepentingan Bersama akan menghapus kerugian', 130, 0, NULL, '2024-11-07 04:04:23', '2024-11-07 04:04:23'),
(645, 'text', 'A.	Mengembangkan sikap sadar hukum dalam kehidupan mulai dari lingkungan paling kecil', 131, 5, NULL, '2024-11-07 04:05:09', '2024-11-07 04:05:09'),
(646, 'text', 'B.	Menjatuhkan sanksi berat terhadap kasus korupsi agar jera dan memberikan pelajaran bagi pejabat lain untuk tidak melakukan Tindakan yang sama', 131, 0, NULL, '2024-11-07 04:05:09', '2024-11-07 04:05:09'),
(647, 'text', 'C.	Menegakakan hukum atas Tindakan kasus kejahatan korupsi secara adil tanpa pandang bulu', 131, 0, NULL, '2024-11-07 04:05:09', '2024-11-07 04:05:09'),
(648, 'text', 'D.	Menggalakakan sosialisasi terkait tindak pidana korupsi dan dampaknya', 131, 0, NULL, '2024-11-07 04:05:09', '2024-11-07 04:05:09'),
(649, 'text', 'E.	Membuat peraturan perundangan-undangan yang tidak memberi celah ruang gerak bagi berkembangnya praktik korupsi', 131, 0, NULL, '2024-11-07 04:05:09', '2024-11-07 04:05:09'),
