(757, 'text', 'Menampung saran dan usul serta berbagai konsep dari anggota BPUPKI', 158, 5, NULL, '2024-12-28 15:30:00', '2024-12-28 15:30:00'),
(758, 'text', 'Mempersiapkan perumusan naskah proklamasi', 158, 0, NULL, '2024-12-28 15:30:00', '2024-12-28 15:30:00'),
(759, 'text', 'Menyusun strategi mengenai dasar hukum negara Indonesia', 158, 0, NULL, '2024-12-28 15:30:00', '2024-12-28 15:30:00'),
(760, 'text', 'Menyamakan nilai-nilai luhur yang dianut nenek moyang bangsa Indonesia dengan dasar negara yang akan disusun', 158, 0, NULL, '2024-12-28 15:30:00', '2024-12-28 15:30:00'),
