(762, 'text', 'Ketuhanan dengan kewajiban melaksanakan hukum-hukum Islam', 159, 0, NULL, '2024-12-28 15:30:39', '2024-12-28 15:30:39'),
(763, 'text', 'Ketuhanan dengan kewajiban mengamalkan ajaran Islam bagi pemeluk-pemeluknya', 159, 0, NULL, '2024-12-28 15:30:39', '2024-12-28 15:30:39'),
(764, 'text', 'Ketuhanan dengan kewajiban menjalankan ibadah Agama Islam bagi pemeluk-pemeluknya', 159, 5, NULL, '2024-12-28 15:30:39', '2024-12-28 15:30:39'),
(765, 'text', 'Ketuhanan dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya', 159, 0, NULL, '2024-12-28 15:30:39', '2024-12-28 15:30:39'),
