(1097, 'text', 'Pengaruh dari negara diluar boundary (batas resmi dua negara). Pengaruh asing tersebut berawal dari budaya, ekonomi, social, agama dan ras.', 227, 0, NULL, '2024-12-28 16:26:03', '2024-12-28 16:26:03'),
