(2004, 'text', 'E. Menyatakan bahwa cara tersebut sudah ketinggalan zaman karena kalau ada yang baik dan halal  kenapa mesti mencari yang haram dan salah', 409, 0, NULL, '2024-12-28 18:22:02', '2024-12-28 18:22:02'),
