(2010, 'text', 'Kekayaan alam dan budaya antardaerah diseragamkan dalam struktur NKRI', 411, 5, NULL, '2024-12-28 18:22:49', '2024-12-28 18:22:49'),
(2011, 'text', 'Bentuk NKRI diselenggarakan dengan jaminan otonomi yang seluas-luasnya kepada daerahdaerah', 411, 0, NULL, '2024-12-28 18:22:49', '2024-12-28 18:22:49'),
(2012, 'text', 'Jaminan otonomi kepada daerah-daerah untuk berkembang sesuai dengan potensi dan kekayaan yang dimilikinya masing-masing', 411, 0, NULL, '2024-12-28 18:22:49', '2024-12-28 18:22:49'),
