(2070, 'text', 'A. Sarjana muda', 423, 0, NULL, '2024-12-28 18:25:38', '2024-12-28 18:25:38'),
(2071, 'text', 'B. Sarjana', 423, 0, NULL, '2024-12-28 18:25:38', '2024-12-28 18:25:38'),
