(2074, 'text', 'E. Profesor', 423, 0, NULL, '2024-12-28 18:25:38', '2024-12-28 18:25:38'),
(2075, 'text', 'a. Jujur mengatakan pada atasan tugasnya terlalu berat', 424, 0, NULL, '2024-12-28 18:26:09', '2024-12-28 18:26:09'),
(2076, 'text', 'b. Meminta keringanan', 424, 0, NULL, '2024-12-28 18:26:09', '2024-12-28 18:26:09'),
(2077, 'text', 'c. Meminta rekan kerja membantu', 424, 0, NULL, '2024-12-28 18:26:09', '2024-12-28 18:26:09'),
(2078, 'text', 'd. Berusaha menyelesaikan sebaik-baikny', 424, 0, NULL, '2024-12-28 18:26:09', '2024-12-28 18:26:09'),
(2079, 'text', 'e. Membiarkan, karena nantinya atasan pasti menyuruh orang lain membantu saya', 424, 0, NULL, '2024-12-28 18:26:09', '2024-12-28 18:26:09'),
(2080, 'text', 'Semboyan persatuan dan kesatuan yang berasal dari keanekaragaman', 425, 0, NULL, '2024-12-28 18:26:10', '2024-12-28 18:26:10'),
(2081, 'text', 'Walaupun terdiri atas berbagai suku yang beranekaragam budaya daerah, tetap satu bangsa Indonesia', 425, 0, NULL, '2024-12-28 18:26:10', '2024-12-28 18:26:10'),
(2082, 'text', 'Memiliki bahasa dan tanah air yang sama, yaitu Bahasa Indonesia dan tanah air Indonesia', 425, 5, NULL, '2024-12-28 18:26:10', '2024-12-28 18:26:10'),
(2083, 'text', 'Bendera kebangsaan merah putih sebagai lambang identitas bangsa dan bersatu padu di bawah falsafah serta dasar negara Pancasila', 425, 0, NULL, '2024-12-28 18:26:10', '2024-12-28 18:26:10'),
(2084, 'text', 'Indonesia beranekaragam budaya, geografis, agama, dan lainnya, maka pedoman masingmasing di antaranya harus dipegang teguh secara sungguh-sungguh dan dipraktikkan dalam kehidupan sehari-hari', 425, 5, NULL, '2024-12-28 18:26:10', '2024-12-28 18:26:10'),
(2085, 'text', 'A. Menurut saja', 426, 0, NULL, '2024-12-28 18:26:20', '2024-12-28 18:26:20'),
(2086, 'text', 'B. Memprotes atasan Anda', 426, 0, NULL, '2024-12-28 18:26:20', '2024-12-28 18:26:20'),
(2087, 'text', 'C. Mengundurkan diri saja', 426, 0, NULL, '2024-12-28 18:26:20', '2024-12-28 18:26:20'),
(2088, 'text', 'D. Mengaduka atasan kepada Komnas HAM', 426, 0, NULL, '2024-12-28 18:26:20', '2024-12-28 18:26:20'),
(2089, 'text', 'E. Memprotes atasan lewat media masa', 426, 0, NULL, '2024-12-28 18:26:20', '2024-12-28 18:26:20'),
(2090, 'text', 'a. Suka menerima masukan demi masukan dalam rangka pengembangan tugas baru saya', 427, 0, NULL, '2024-12-28 18:26:41', '2024-12-28 18:26:41'),
(2091, 'text', 'b. Membicarakan hal-hal lain yang tidak ada kaitannya dengan tugas baru saya', 427, 0, NULL, '2024-12-28 18:26:41', '2024-12-28 18:26:41'),
(2092, 'text', 'c. Membatasi pembicaraan agar tidak menyangkut ke hal-hal tugas baru say', 427, 0, NULL, '2024-12-28 18:26:41', '2024-12-28 18:26:41'),
(2093, 'text', 'd. Akan merasa gelisah dan kurang senang bila mereka mulai membicarakan tugas baru say', 427, 0, NULL, '2024-12-28 18:26:41', '2024-12-28 18:26:41'),
(2094, 'text', 'd. Akan merasa gelisah dan kurang senang bila mereka mulai membicarakan tugas baru say', 427, 0, NULL, '2024-12-28 18:26:41', '2024-12-28 18:26:41'),
(2095, 'text', 'A. Mengurungkan keinginan untuk melanjutkan pendidikan', 428, 0, NULL, '2024-12-28 18:27:01', '2024-12-28 18:27:01'),
(2096, 'text', 'B. Meminta orang tua untuk tetap menyekolahkan', 428, 0, NULL, '2024-12-28 18:27:01', '2024-12-28 18:27:01'),
(2097, 'text', 'C. Bekerja sambilan untuk mengumpulkan dana pendidikan', 428, 0, NULL, '2024-12-28 18:27:01', '2024-12-28 18:27:01'),
(2098, 'text', 'D. Mencari beasiswa yang bisa membuat saya melanjutkan pendidikan', 428, 0, NULL, '2024-12-28 18:27:01', '2024-12-28 18:27:01'),
(2099, 'text', 'E. Mencari orang tua asuh yag mampu membiayai saya', 428, 0, NULL, '2024-12-28 18:27:01', '2024-12-28 18:27:01'),
(2100, 'text', 'a. Saya menuntutnya untuk meningkatkan kemampuannya', 429, 0, NULL, '2024-12-28 18:27:09', '2024-12-28 18:27:09'),
(2101, 'text', 'b. Saya menegaskan bila dia tidak meningkatkan kemampuannya, maka saya tidak segan akan memberhentikannya', 429, 0, NULL, '2024-12-28 18:27:09', '2024-12-28 18:27:09'),
(2102, 'text', 'c. Saya akan memberhentikannya dengan segera', 429, 0, NULL, '2024-12-28 18:27:09', '2024-12-28 18:27:09'),
(2103, 'text', 'd. Saya meminta atasan saya untuk memindahkannya ke unit lain', 429, 0, NULL, '2024-12-28 18:27:09', '2024-12-28 18:27:09'),
(2104, 'text', 'e. Saya membimbingnya dan memintanya untuk meningkatkan', 429, 0, NULL, '2024-12-28 18:27:09', '2024-12-28 18:27:09'),
(2105, 'text', 'a. Mumpung masih di kantor dengan fasilitas internet, maka saya pergunakan untuk mengakses situs jaringan sosial facebook', 430, 0, NULL, '2024-12-28 18:27:42', '2024-12-28 18:27:42'),
(2106, 'text', 'b. Setelah lelah bekerja hari ini, saya rasa tak ada salahnya saya mengobrol dengan rekanrekan kerja lain untuk sekedar mengisi wakt', 430, 0, NULL, '2024-12-28 18:27:42', '2024-12-28 18:27:42'),
(2107, 'text', 'c. Saya lebih suka membaca tabloid infotainment', 430, 0, NULL, '2024-12-28 18:27:42', '2024-12-28 18:27:42'),
(2108, 'text', 'd. Saya pergunakan untuk chatting dengan kawan lama', 430, 0, NULL, '2024-12-28 18:27:42', '2024-12-28 18:27:42'),
(2109, 'text', 'e. Saya pergunakan untuk membaca buku-buku pengemb', 430, 0, NULL, '2024-12-28 18:27:42', '2024-12-28 18:27:42'),
(2110, 'text', 'A. Memberi mereka hukuman bila masih pasif.', 431, 0, NULL, '2024-12-28 18:27:46', '2024-12-28 18:27:46'),
(2111, 'text', 'B. Memberi reward bagi anggota yang mau mengubah diri menjadi aktif.', 431, 0, NULL, '2024-12-28 18:27:46', '2024-12-28 18:27:46'),
(2112, 'text', 'C. Melibatkan diri mereka ke dalam suatu kegiatan yang menuntut mereka bertindak aktif dan kreatif.', 431, 0, NULL, '2024-12-28 18:27:46', '2024-12-28 18:27:46'),
(2113, 'text', 'D. Memindahkan mereka ke tim kerja lain.', 431, 0, NULL, '2024-12-28 18:27:46', '2024-12-28 18:27:46'),
(2114, 'text', 'E. Mengasingkan mereka yang aktif dan merangkul yang aktif.', 431, 0, NULL, '2024-12-28 18:27:46', '2024-12-28 18:27:46'),
