(2119, 'text', 'e. Meminta bantuan orang lain', 432, 0, NULL, '2024-12-28 18:28:10', '2024-12-28 18:28:10'),
(2120, 'text', 'A. Mengetahui pendapatnya tentang suatu peristiwa.', 433, 0, NULL, '2024-12-28 18:28:28', '2024-12-28 18:28:28'),
(2121, 'text', 'B. Untuk menguji wawasan serta kepedulianya terhadap lingkungan sekitar.', 433, 0, NULL, '2024-12-28 18:28:28', '2024-12-28 18:28:28'),
(2122, 'text', 'C. Untuk mengetahui kemampuannya dalam berkomunikasi.', 433, 0, NULL, '2024-12-28 18:28:28', '2024-12-28 18:28:28'),
(2123, 'text', 'D. Untuk melihat aura bintang dalam setiap komentarnya.', 433, 0, NULL, '2024-12-28 18:28:28', '2024-12-28 18:28:28'),
(2124, 'text', 'E. Untuk mengetahui kepedulian seseorang terhadap peristiwa serta kemampuan untuk problem  solving.', 433, 0, NULL, '2024-12-28 18:28:28', '2024-12-28 18:28:28'),
